L["ABOUT_TEXT"] = "LazyGCore 使用为全部九个职业研究的 World of Warcraft: Forever 优先级列表来建议你的下一个技能，并指导你的天赋选择。\n\nForever 运行在现代 WoW 引擎上，该引擎会对插件隐藏部分战斗信息（目标生命值、部分光环、战斗记录）。LazyGCore 通过安全层读取所有信息：当游戏隐藏某个数值时，LazyGCore 会改用自身的施法追踪或 Blizzard 的“可用”反应式检查，而不是猜测。\n\n如果某个建议看起来不对，请将引擎切换为“LazyGCore + Blizzard 后备”或“Blizzard 辅助战斗”，并使用 /lazygcore check 和 /lazygcore status 报告你的客户端显示的内容。\n\n命令：/lazygcore, /lazygcore talents, /lazygcore toggle, /lazygcore spec <name / auto>, /lazygcore engine <lazygcore / hybrid / blizzard>。"

