L["Your Curse slot: +10% magic damage taken."] = "你的诅咒栏位：受到的魔法伤害+10%。"
L["Your Curse slot: armor down for the group (target ignores Fear)."] = "你的诅咒栏位：为小队降低护甲（目标免疫恐惧）。"
