L["Dungeons before Master Demonologist: Blood Pact + Firebolt."] = "学会恶魔学识大师前的地下城：血之契印+火焰箭。"
L["Low health: Bear, then Frenzied Regeneration."] = "生命值低：变熊，然后狂暴回复。"
L["Hard-hitting filler with Improved Starfire."] = "配合强化星火术的高伤害填充技能。"
L["Threat on every mob, less damage taken."] = "对每个怪物产生仇恨，受到的伤害降低。"

L["Cheetah / Pack is on in combat: every hit dazes you."] = "战斗中仍开着猎豹/豹群守护：每次被击中都会被眩晕。"
L["You have aggro - drop threat."] = "你拉到了仇恨 - 降低仇恨。"
L["Melee: more dodge, and dodges enable Mongoose Bite."] = "近战：提高躲闪，躲闪后可使用猫鼬撕咬。"
L["Group health hidden - mouse over who to heal"] = "队伍生命值隐藏 - 将鼠标悬停在要治疗的人身上"
L["Immune to attacks and spells for 6-8s, but you can't attack; Forbearance after."] = "6-8秒内免疫攻击和法术，但你无法攻击；之后获得自律。"
L["Hard hits incoming: +30% block for 10s."] = "重击来袭：格挡几率提高30%，持续10秒。"
L["+30% block; every block deals Holy damage and threat to the pack."] = "格挡几率提高30%；每次格挡对怪群造成神圣伤害和仇恨。"
L["Instant damage between Auto Shots."] = "自动射击之间的瞬发伤害。"
L["Out of melee: sting it while you close in."] = "不在近战范围：靠近时施放钉刺。"
L["Hit plus a Fire DoT."] = "直接伤害加一个火焰持续伤害。"
L["One more DoT while the target lives long enough."] = "目标存活时间够长时再加一个持续伤害。"
L["Heal up between pulls."] = "两波怪之间回血。"
L["Pack is down - back to Cat."] = "这波怪已清 - 变回猎豹形态。"
L["You tank this group: Bear Form."] = "你是本队坦克：熊形态。"
L["Feral in groups:"] = "野性德在队伍中："
L["Bear (tank)"] = "熊（坦克）"
L["Cat (damage)"] = "猎豹（伤害）"
L["Pool energy for Ghostly Strike."] = "为鬼魅攻击攒能量。"
L["Renew yourself: heals over 15s while you keep casting."] = "对自己施放恢复：在你继续施法时持续治疗15秒。"
L["Instant hit plus a 12s Fire DoT."] = "瞬发伤害，外加12秒火焰持续伤害。"
L["Regrowth is ticking - Healing Touch for the rest."] = "愈合正在生效 - 用治疗之触补足剩余血量。"
L["Low health: absorb the next hits."] = "生命值低：吸收接下来的伤害。"
L["Your main nuke."] = "你的主力输出法术。"
L["Damage and a 40% slow on everything in front of you."] = "对你面前的所有敌人造成伤害并减速40%。"
L["Shadow DoT: keep it ticking."] = "暗影持续伤害：保持生效。"
L["Channeled: hits everything in the area for 6s."] = "引导：6秒内攻击区域内的所有敌人。"
L["At your feet: Fire damage to every mob within 10 yd."] = "放在脚下：对10码内的所有怪物造成火焰伤害。"
L["At your feet: burns the first mob to reach it."] = "放在脚下：灼烧第一个踩到它的怪物。"
L["Weapon-damage kick, 8s cooldown (+30% run speed)."] = "造成武器伤害的踢击，8秒冷却（移动速度+30%）。"
L["21s bleed: keep it on targets that live."] = "21秒流血：对能活得久的目标保持。"
L["Single target: your hardest-hitting shot."] = "单体：你伤害最高的射击。"
L["Hits up to 4 enemies around you."] = "攻击你周围最多4个敌人。"
L["Open with Charge, then Berserker Stance."] = "用冲锋起手，然后切换狂暴姿态。"
L["Before Whirlwind (36) Fury fights here: Rend and Overpower."] = "学会旋风斩（36级）前狂暴战在此姿态作战：撕裂和压制。"
L["Pool energy for Backstab."] = "为背刺攒能量。"
L["In danger: quick heal on yourself."] = "危险：快速治疗自己。"
L["Hurt: Renew yourself and keep casting."] = "受伤：给自己恢复，继续施法。"
L["Shadowform filler."] = "暗影形态下的填充技能。"
L["Filler: out-damages the wand."] = "填充技能：伤害高于魔杖。"
L["Group health hidden: a cheap heal on the tank (mouse over whoever needs it)."] = "队伍血量被隐藏：给坦克一个廉价治疗（鼠标指向需要的人）。"
-- ============================================================================
-- OPTION TOOLTIPS (hover explanations of the options window controls)
-- ============================================================================
L["Turns LazyGCore on or off. Off hides the display and stops all suggestions, action bar glows, alerts and sounds."] = "开启或关闭 LazyGCore。关闭后会隐藏显示框，并停止所有建议、动作条发光、警报和声音。"
L["Keeps the display where it is. While locked the icon ignores the mouse, so clicks pass through to the game; unlock it to drag the display somewhere else."] = "固定显示框的位置。锁定时图标不响应鼠标，点击会直接作用到游戏中；解锁后可将显示框拖到其他位置。"
L["Shows the LazyGCore button on the minimap. Click: these options. Ctrl+Click: show or hide the display. Shift+Click: Stats window. Alt+Click: talents."] = "在小地图上显示 LazyGCore 按钮。点击：打开这些选项。Ctrl+点击：显示或隐藏显示框。Shift+点击：统计窗口。Alt+点击：天赋。"
L["Where the suggestions come from. LazyGCore priorities: LazyGCore's own rotation for your spec. LazyGCore + Blizzard fallback: LazyGCore first, and only when LazyGCore has nothing to suggest, Blizzard's Assisted Combat pick is shown. Blizzard Assisted Combat: Blizzard's pick on the main icon, LazyGCore's next spells in the queue."] = "建议的来源。“LazyGCore 优先级”：LazyGCore 为你的专精设计的循环。“LazyGCore + Blizzard 后备”：优先使用 LazyGCore，仅当 LazyGCore 没有可建议的技能时才显示 Blizzard 辅助战斗的选择。“Blizzard 辅助战斗”：主图标显示 Blizzard 的选择，队列中显示 LazyGCore 的后续法术。"
L["Which spec's rotation LazyGCore follows on this character. Auto picks the talent tree with the most points (the Leveling rotation before you spend any). Pick a spec to force it; it goes back to Auto when you switch talent specs."] = "LazyGCore 在此角色上采用哪个专精的循环。“自动”会选择投入点数最多的天赋树（尚未分配点数时使用升级循环）。选择某个专精可强制使用它；切换天赋专精时会恢复为“自动”。"
L["Shows the rotation display. Off hides it (with its alerts) everywhere, even in combat, while the action bar glow keeps following the suggestions. Same as /lazygcore toggle."] = "显示循环显示框。关闭后在任何地方（包括战斗中）都隐藏显示框及其警报，但动作条发光仍会跟随建议。等同于 /lazygcore toggle。"
L["Keeps the display on screen out of combat too. Off (default): it shows in combat, plus the two cases below."] = "脱离战斗时也将显示框保留在屏幕上。关闭（默认）：仅在战斗中显示，以及下面两种情况。"
L["Out of combat, also show the display while you target an enemy, so you see the opener before the pull. Only applies when Show out of combat is off."] = "脱离战斗时，选中敌人期间也显示显示框，以便在开怪前看到起手技能。仅在“非战斗显示”关闭时生效。"
L["Out of combat, also show the display when it suggests a missing buff, pet, poison or weapon imbue, and hide it again once done. Only applies when Show out of combat is off and Suggest buffs & pets (Combat page) is on."] = "脱离战斗时，当建议补上缺少的增益、宠物、毒药或武器附魔时也显示显示框，处理完后再次隐藏。仅在“非战斗显示”关闭且“建议增益和宠物”（“战斗”页面）开启时生效。"
L["Out of combat, hide the display while there is nothing to suggest instead of showing the LazyGCore logo. Only applies when Show out of combat is on."] = "脱离战斗时，没有可建议的内容就隐藏显示框，而不是显示 LazyGCore 标志。仅在“非战斗显示”开启时生效。"
L["Shows the spell part of the display: main icon, cooldown icon, history, queue, spell name and reason. Off hides those; the ring (swing timer), warning line, alerts, buff tracker and DPS strip stay, and the action bar glow still works."] = "显示显示框的法术部分：主图标、冷却图标、历史、队列、法术名称和原因。关闭后这些会隐藏；圆环（攻击计时器）、警告行、警报、增益追踪和DPS条保留，动作条发光仍然有效。"
L["Color of the ring around the main icon, the DPS strip accent and the Auto action bar glow. Auto (Match Spec) uses your spec's color."] = "主图标周围圆环、DPS条强调色以及自动动作条发光的颜色。“自动（匹配专精）”使用你专精的颜色。"
L["Look of LazyGCore's windows: these options, the Stats window and the talent windows. Default is the classic WoW gold style."] = "LazyGCore 窗口的外观：这些选项、统计窗口和天赋窗口。默认为经典的 WoW 金色风格。"
L["Size of the whole rotation display: icons, text and DPS strip. Does not change LazyGCore's windows. Default 1.0."] = "整个循环显示框的大小：图标、文字和DPS条。不会改变 LazyGCore 的窗口。默认 1.0。"
L["Size of the main spell icon in pixels, before Scale. The cooldown icon grows with it. Default 72."] = "主法术图标的大小（像素，缩放前）。冷却图标会随之变大。默认 72。"
L["Opacity of the whole rotation display: icons, text, warning line, alerts and DPS strip. 1 = fully visible."] = "整个循环显示框的不透明度：图标、文字、警告行、警报和DPS条。1 = 完全可见。"
L["Opacity of the spell icons only: the main icon and its ring, the cooldown icon, the spell history and the queue (NEXT). The text stays fully visible."] = "仅法术图标的不透明度：主图标及其圆环、冷却图标、施法历史和队列（下一）。文字保持完全可见。"
L["Dark box behind the rotation display. 0 (default) = no box; higher = a more solid box."] = "循环显示框后面的深色背景框。0（默认）= 无背景框；数值越高背景框越不透明。"
L["Moves the rotation display back to its default spot below the middle of the screen."] = "将循环显示框移回默认位置（屏幕中央下方）。"
L["Sets Spec template back to Auto and detects your spec from your talents again."] = "将“专精模板”恢复为“自动”，并重新根据你的天赋检测专精。"
L["Opens or closes the floating Stats window (DPS, parse estimate, live stats)."] = "打开或关闭浮动统计窗口（DPS、解析估算、实时数据）。"
L["Opens or closes the Talent Guide window with the recommended talent build for your spec."] = "打开或关闭“天赋指南”窗口，其中包含你专精的推荐天赋方案。"
L["Shows the key bound to the suggested spell in the top-right corner of the main icon, read from your action bars."] = "在主图标右上角显示建议法术绑定的按键（从你的动作条读取）。"
L["Shows a gold star in the top-left corner of the main icon when the suggestion comes from a proc."] = "当建议来自触发效果时，在主图标左上角显示一颗金色星星。"
L["Shows 'Out of Range' over the main icon and greys it out when your target is out of range of the suggested spell."] = "当目标超出建议法术的射程时，在主图标上显示“超出范围”并将其变灰。"
L["Shows a badge with the enemy count in the bottom-left corner of the main icon when enough enemies are near for AoE."] = "当附近敌人足够多可以使用AoE时，在主图标左下角显示敌人数量标记。"
L["Shows the global cooldown sweep over the main icon after each cast. Off by default."] = "每次施法后在主图标上显示公共冷却转圈。默认关闭。"
L["Healers: shows the name of the group member a heal is suggested for at the bottom of the main icon (not for yourself or your target)."] = "治疗者：在主图标底部显示建议治疗的队友名字（自己或当前目标除外）。"
L["Shows a smaller icon right of the main icon for your next major cooldown, racial or on-use trinket: green pulse when ready, grey while it recharges. Off: cooldowns go into the queue instead."] = "在主图标右侧显示一个较小的图标，用于你的下一个主要冷却技能、种族技能或主动饰品：就绪时绿色闪烁，冷却中为灰色。关闭：冷却技能改为进入队列。"
L["Size of the cooldown icon compared to the main icon (0.65 = 65%). Only applies when Cooldown icon is on."] = "冷却图标相对于主图标的大小（0.65 = 65%）。仅在“冷却图标”开启时生效。"
L["Shows your last casts as small icons left of the main icon (PREV), newest nearest to it."] = "以小图标的形式在主图标左侧显示你最近的施法（上一），最新的离主图标最近。"
L["How many past casts to show. Only applies when Spell history is on."] = "显示多少次过去的施法。仅在“施法历史”开启时生效。"
L["Size of the history icons in pixels. Only applies when Spell history is on."] = "历史图标的大小（像素）。仅在“施法历史”开启时生效。"
L["On (default): history, main icon, cooldown icon and queue sit in one row. Off: the classic layout with the queue under the spell name."] = "开启（默认）：历史、主图标、冷却图标和队列排成一行。关闭：经典布局，队列位于法术名称下方。"
L["Shows the spells LazyGCore expects to suggest after the current one (NEXT)."] = "显示 LazyGCore 预计在当前法术之后建议的法术（下一）。"
L["How many upcoming spells to show. Only applies when Priority queue is on."] = "显示多少个后续法术。仅在“优先队列”开启时生效。"
L["Size of the queue icons in pixels. Only applies when Priority queue is on."] = "队列图标的大小（像素）。仅在“优先队列”开启时生效。"
L["Shows the name of the suggested spell under the main icon."] = "在主图标下方显示建议法术的名称。"
L["Shows a short reason under the spell name: why this spell is suggested now, or why the rotation is paused."] = "在法术名称下方显示简短原因：为什么现在建议这个法术，或循环为什么暂停。"
L["Hides the spell name, the reason text and the DPS strip in one go (in the classic layout also the queue), whatever their own toggles say. Same as /lazygcore hidename."] = "一次性隐藏法术名称、原因文本和DPS条（经典布局下也包括队列），无论它们各自的开关如何设置。等同于 /lazygcore hidename。"
L["Shows a health bar for your target above the main icon."] = "在主图标上方显示目标的生命条。"
L["Shows the warning line above the icon: buff reminders, a suggested spell missing from your action bars, a lower rank on your bars, a paused rotation. Off hides all of them."] = "在图标上方显示警告行：增益提醒、建议的法术不在动作条上、动作条上是低等级法术、循环已暂停。关闭后全部隐藏。"
L["Out of combat, the warning line names a missing buff ('Recommended: ...') or one about to run out, with its time left. Only applies when Warning line is on."] = "脱离战斗时，警告行会显示缺少的增益（“推荐: ...”）或即将消失的增益及其剩余时间。仅在“警告行”开启时生效。"
L["Out of combat, the warning line lists up to three missing buffs ('Missing: ...') instead of naming only one. Only applies when Warning line is on."] = "脱离战斗时，警告行最多列出三个缺少的增益（“缺少: ...”），而不是只显示一个。仅在“警告行”开启时生效。"
L["Shows a row of small icons under the display with your important buffs and your damage over time spells on the target, with their time left."] = "在显示框下方显示一排小图标，包括你的重要增益以及你在目标身上的持续伤害法术，并显示剩余时间。"
L["Puts your active procs (Clearcasting, Shadow Trance, ...) first in the buff tracker. Only applies when Buff tracker is on."] = "将你当前激活的触发效果（节能施法、暗影冥思等）排在增益追踪的最前面。仅在“增益追踪”开启时生效。"
L["Fades the display while there is nothing to suggest. How far is set by Idle Transparency."] = "没有可建议的内容时淡化显示框。淡化程度由“空闲透明度”设置。"
L["Shows your melee swing (Hunters: Auto Shot) on the ring around the main icon; it pulses when the next swing is ready. Only applies when Show outline is on."] = "在主图标周围的圆环上显示你的近战攻击计时（猎人：自动射击）；下一次攻击就绪时圆环会闪烁。仅在“显示轮廓”开启时生效。"
L["How visible the display stays while idle, as a share of Overall Transparency (0.3 = 30%). Only applies when Fade when idle is on."] = "空闲时显示框保持的可见度，按“整体透明度”的比例计算（0.3 = 30%）。仅在“空闲时淡出”开启时生效。"
L["Makes the action bar button of the suggested spell glow, so you find it at a glance."] = "让建议法术所在的动作条按钮发光，方便你一眼找到。"
L["Look of that glow: LazyGCore glow (soft breathing glow), Marching ants, or Blizzard's own proc glow. Only applies when Glow the suggested spell is on."] = "发光的样式：LazyGCore 发光（柔和的呼吸光）、蚂蚁线或 Blizzard 自带的触发发光。仅在“建议法术发光”开启时生效。"
L["Color of that glow. Auto (Match Spec) uses your theme color. Only applies when Glow the suggested spell is on."] = "发光的颜色。“自动（匹配专精）”使用你的主题颜色。仅在“建议法术发光”开启时生效。"
L["When the suggested spell is not on your action bars, the spellbook button and the spell inside the spellbook glow, so you can drag it to a bar."] = "当建议的法术不在你的动作条上时，法术书按钮和法术书中的该法术会发光，方便你将其拖到动作条上。"
L["When a bar button holds a lower rank of the suggested spell, its glow turns orange and the warning line says which rank to put there."] = "当动作条按钮上是建议法术的较低等级时，其发光会变为橙色，警告行会提示应放哪个等级。"
L["Makes the action bar buttons of your spec's major cooldowns glow whenever they are ready, separately from the glow on the suggested spell."] = "你专精的主要冷却技能就绪时，让对应的动作条按钮发光，与建议法术的发光相互独立。"
L["Color of the cooldown glow (default green). Only applies when Enable Cooldown Glow is on."] = "冷却发光的颜色（默认绿色）。仅在“启用冷却发光”开启时生效。"
L["Adds swing bars inside the main icon: main hand (gold), off hand (blue) and ranged (green, GO when ready)."] = "在主图标内添加攻击计时条：主手（金色）、副手（蓝色）和远程（绿色，就绪时显示GO）。"
L["Starts or stops a test swing so you can see the swing timer without fighting."] = "开始或停止一次测试攻击，无需战斗即可查看攻击计时器。"
L["Includes your major offensive cooldowns, racials and on-use trinkets in the suggestions (in combat, with a target)."] = "在建议中包含你的主要进攻冷却技能、种族技能和主动饰品（战斗中且有目标时）。"
L["Suggests defensive spells and escapes when you are in danger: low health, stunned or feared. Also needed for the heal-your-pet and mana gem suggestions."] = "当你处于危险中时建议防御技能和脱身技能：生命值低、被昏迷或被恐惧。治疗宠物和法力宝石的建议也需要开启此项。"
L["Out of combat, the main icon suggests missing self-buffs, poisons and weapon imbues, calling or reviving your pet, and healing up between pulls."] = "脱离战斗时，主图标会建议补上缺少的自身增益、毒药和武器附魔，召唤或复活宠物，以及在两次开怪之间回血。"
L["Lets LazyGCore switch to your spec's AoE spells when at least AoE enemy threshold enemies are near."] = "当附近敌人数量至少达到“AoE敌人数量阈值”时，允许 LazyGCore 切换为你专精的AoE法术。"
L["Allows AoE suggestions in battlegrounds and against players. Off by default, because every nearby player counts as an enemy. Only applies when Enable AoE suggestions is on."] = "允许在战场中和对抗玩家时给出AoE建议。默认关闭，因为附近的每个玩家都会被算作敌人。仅在“启用AoE建议”开启时生效。"
L["How many enemies are needed for AoE suggestions (default 3). LazyGCore counts living enemies in combat within about 10 yards, or in range of your ranged AoE spell, from their nameplates, so enemy nameplates must be on."] = "AoE建议所需的敌人数量（默认 3）。LazyGCore 根据姓名板统计约10码内或你远程AoE法术射程内处于战斗中的存活敌人，因此必须开启敌方姓名板。"
L["Keeps the current suggestion for 0.3 seconds when another spell would briefly take over, so the icon doesn't flicker. Defensives always switch at once."] = "当另一个法术只会短暂取代当前建议时，将当前建议保持0.3秒，以免图标闪烁。防御技能总是立即切换。"
L["Suggests your race's abilities, such as Berserking or Stoneform, along with your other spells."] = "将你的种族技能（例如狂暴或石像形态）与其他法术一起建议。"
L["Shows ready on-use trinkets in the cooldown slot, and your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "在冷却栏位显示已就绪的主动饰品；被昏迷或被恐惧时显示你的PvP饰品（需开启“建议防御技能”）。"
L["Healers: never suggest damage spells, not even solo."] = "治疗者：从不建议伤害法术，单人时也不建议。"
L["Healers in a group: suggest damage spells while nobody needs healing. Solo, healers always get damage suggestions."] = "组队中的治疗者：没有人需要治疗时建议伤害法术。单人时，治疗者总是会得到伤害建议。"
L["Healers: heal suggestions are for the friendly player under your mouse when there is one. Changes the suggestion target only - it never targets anything."] = "治疗者：鼠标下有友方玩家时，治疗建议针对该玩家。这只改变建议的目标，绝不会替你选择任何目标。"
L["Shows a KICK! box to the left of the icon (left of the spell history when it shows) when your enemy target casts something you can interrupt and your interrupt is ready."] = "当敌对目标正在施放可打断的法术且你的打断技能已就绪时，在图标左侧（显示法术历史时在其左侧）显示“打断！”框。"
L["Shows a DEFENSIVE! box in combat when your health drops below Defensive Threshold and a defensive spell is ready."] = "战斗中当你的生命值低于“防御阈值”且有防御技能就绪时，显示“防御！”框。"
L["Your health % below which the DEFENSIVE! box appears (default 35%). Only applies when Defensive Alerts is on."] = "生命值低于此%时显示“防御！”框（默认 35%）。仅在“防御警报”开启时生效。"
L["Out of combat, shows a PURGE box when your enemy target has a magic buff and your purge or dispel is ready."] = "脱离战斗时，当敌对目标拥有魔法增益且你的净化或驱散技能已就绪时，显示“净化”框。"
L["Shows EXECUTE! on the main icon while your enemy target is below Execute threshold. Only if you know Execute, Hammer of Wrath or Shadow Word: Death."] = "敌对目标生命值低于“斩杀阈值”时在主图标上显示“斩杀!”。仅在你学会斩杀、愤怒之锤或暗言术：灭时生效。"
L["Target health % below which EXECUTE! shows (default 20%). Only applies when Execute phase is on."] = "目标生命值低于此%时显示“斩杀!”（默认 20%）。仅在“斩杀阶段”开启时生效。"
L["In combat, warns above the icon when your mana, rage or energy (and your pet's health) drops below the thresholds below."] = "战斗中，当你的法力值、怒气或能量（以及宠物生命值）低于下方阈值时，在图标上方发出警告。"
L["Mana % below which the low mana warning shows (default 20%). Only applies when Low resource warnings is on."] = "法力值低于此%时显示法力不足警告（默认 20%）。仅在“资源不足警告”开启时生效。"
L["Rage below which the low rage warning shows (default 20). Only applies when Low resource warnings is on."] = "怒气低于此值时显示怒气不足警告（默认 20）。仅在“资源不足警告”开启时生效。"
L["Energy below which the low energy warning shows (default 30). Only applies when Low resource warnings is on."] = "能量低于此值时显示能量不足警告（默认 30）。仅在“资源不足警告”开启时生效。"
L["Pet health % below which the pet warning shows (default 30%). Only applies when Low resource warnings is on."] = "宠物生命值低于此%时显示宠物警告（默认 30%）。仅在“资源不足警告”开启时生效。"
L["Shows the KICK! box for 3 seconds so you can see where it appears."] = "显示“打断！”框3秒，让你看到它出现的位置。"
L["Shows the DEFENSIVE! box for 3 seconds so you can see where it appears."] = "显示“防御！”框3秒，让你看到它出现的位置。"
L["Shows the PURGE box for 3 seconds so you can see where it appears."] = "显示“净化”框3秒，让你看到它出现的位置。"
L["Plays the alert sound when a KICK!, DEFENSIVE! or PURGE box appears, on low resource warnings and when a buff goes missing. Off by default."] = "出现“打断！”、“防御！”或“净化”框、资源不足警告以及缺少增益时播放警报声音。默认关闭。"
L["Silences every sound LazyGCore plays, including the proc and weapon buff sounds."] = "静音 LazyGCore 播放的所有声音，包括触发和武器增益的声音。"
L["Plays a sound when a proc becomes the suggestion. Works even with Sound alerts off."] = "当触发效果成为建议时播放声音。即使“声音警报”关闭也有效。"
L["Which sound the alerts play. Only applies when Sound alerts is on."] = "警报播放的声音。仅在“声音警报”开启时生效。"
L["Plays the chosen alert sound once."] = "播放一次所选的警报声音。"
L["How often suggestions are recalculated in combat. Faster reacts sooner but uses more CPU; casts, cooldowns and target changes refresh at once anyway. Default 20 per second."] = "战斗中重新计算建议的频率。越快反应越及时，但占用更多CPU；施法、冷却和目标变化无论如何都会立即刷新。默认每秒20次。"
L["How often suggestions are recalculated out of combat. Slower saves CPU between fights; it is never faster than Update rate. Default 2 per second."] = "脱离战斗时重新计算建议的频率。越慢越能在战斗间隙节省CPU；不会快于“更新频率”。默认每秒2次。"
L["Prints extra diagnostic messages to chat. Errors are reported either way; leave this off unless you are tracking down a problem."] = "在聊天框输出额外的诊断信息。错误总会报告；除非你在排查问题，否则请保持关闭。"
L["Prints LazyGCore's status to chat: version, class, spec, engine and the settings that affect suggestions. Useful for bug reports."] = "在聊天框输出 LazyGCore 的状态：版本、职业、专精、引擎以及影响建议的设置。适合用于报告问题。"
L["Prints which spells of your class rotation you know and which are still missing from your spellbook."] = "在聊天框输出你已学会的职业循环法术，以及法术书中还缺少哪些。"
L["Turns on the game's Lua error pop-ups, to see errors from any addon."] = "开启游戏的Lua错误弹窗，以便查看任何插件的错误。"
L["Turns off the game's Lua error pop-ups."] = "关闭游戏的Lua错误弹窗。"
L["Prints the buffs and procs the buff tracker watches for your spec to chat."] = "在聊天框输出增益追踪为你的专精监视的增益和触发效果。"
L["Prints what LazyGCore suggests right now, and why, to chat."] = "在聊天框输出 LazyGCore 当前建议的内容及原因。"
L["Prints the details behind the DPS/HPS numbers to chat."] = "在聊天框输出DPS/HPS数值背后的详细信息。"
L["Resets every account-wide LazyGCore setting to its default after you confirm. Your saved profiles and this character's spec, talent build and custom rotations are kept."] = "确认后将 LazyGCore 的所有账号通用设置恢复为默认。你保存的配置文件以及该角色的专精、天赋方案和自定义循环会保留。"
L["Makes the action bar buttons holding this spell glow for 5 seconds, to check that LazyGCore finds it. Empty box: the current suggestion."] = "让放有此法术的动作条按钮发光5秒，以检查 LazyGCore 能否找到它。输入框为空时：使用当前建议。"
L["Removes the test glow."] = "移除测试发光。"
L["Spell to test: type its name, or leave the box empty for the current suggestion. Enter or Test makes its action bar buttons glow."] = "要测试的法术：输入其名称，或留空以使用当前建议。按回车或测试会让它在动作条上的按钮发光。"
L["Language of LazyGCore's text. Auto uses your game client's language. Applies after a UI reload."] = "LazyGCore 文字的语言。“自动”使用你游戏客户端的语言。重载界面后生效。"
L["Reloads the interface now, so a new language takes effect."] = "立即重载界面，使新语言生效。"
L["Sets every option on this page back to its default."] = "将此页面上的所有选项恢复为默认。"
L["Switches between your custom rotation and LazyGCore's default priority for this spec."] = "在你的自定义循环与 LazyGCore 为此专精设定的默认优先级之间切换。"
L["When the spell is suggested. Conditions marked * are estimates in combat, because Forever hides health, mana and most auras there."] = "何时建议该法术。标有 * 的条件在战斗中为估算值，因为 Forever 在战斗中会隐藏生命值、法力值和大部分光环。"
L["Adds the spell typed in the box to the end of your list, with the condition chosen beside it."] = "将输入框中的法术添加到列表末尾，并使用旁边选择的条件。"
L["Gives the entry selected in the list the spell, condition and values chosen here. A default rule becomes your own rule."] = "将此处选择的法术、条件和数值应用到列表中选中的条目。默认规则会变成你自己的规则。"
L["Fills the list with LazyGCore's default priority for your current spec, so you can edit it."] = "用 LazyGCore 为你当前专精设定的默认优先级填充列表，方便你编辑。"
L["Saves the list as this spec's saved rotation."] = "将列表保存为此专精的已保存循环。"
L["Loads this spec's saved rotation into the list."] = "将此专精的已保存循环加载到列表中。"
L["No saved rotation for this spec yet: use Save Custom first."] = "此专精还没有已保存的循环：请先使用“保存自定义”。"
L["Removes every spell from the list, after you confirm."] = "确认后移除列表中的所有法术。"
L["Saves the list under the name typed in the box, so you can keep several rotations."] = "以输入框中的名称保存列表，这样你可以保留多个循环。"
L["Your named rotations, with their spec and number of spells. Pick one, then Load or Delete it."] = "你命名的循环，及其专精和法术数量。选择一个，然后加载或删除。"
L["Loads the named rotation picked beside it into the list."] = "将旁边选择的命名循环加载到列表中。"
L["Deletes the named rotation picked beside it, after you confirm."] = "确认后删除旁边选择的命名循环。"
L["Gives the named rotation picked below the name typed in the box."] = "将下方选择的命名循环改为输入框中的名称。"
L["LazyGCore suggests from your list above instead of its default priority for this spec. Defensives and the cooldown slot still work as usual."] = "LazyGCore 会根据你上方的列表给出建议，而不是此专精的默认优先级。防御技能和冷却栏位照常工作。"
L["When nothing in your list is ready, the default priority fills in. Only applies when Use Custom Rotation is on."] = "当你列表中没有法术就绪时，由默认优先级补位。仅在“使用自定义循环”开启时生效。"
L["Never suggest the spell typed in the box (also not in the cooldown slot or the cooldown glow)."] = "从不建议输入框中的法术（冷却栏位和冷却发光中也不会出现）。"
L["Lets the spell in the box, or the one selected in the list, be suggested again."] = "让输入框中的法术或列表中选中的法术重新可以被建议。"
L["Prints every excluded spell to chat."] = "在聊天框输出所有被排除的法术。"
L["Removes every exclusion, after you confirm."] = "确认后移除所有排除项。"
L["Turns LazyGCore off while you are in a battleground: no display, suggestions or glows there."] = "在战场中关闭 LazyGCore：不显示显示框、建议或发光。"
L["Turns LazyGCore off while you are in an arena: no display, suggestions or glows there."] = "在竞技场中关闭 LazyGCore：不显示显示框、建议或发光。"
L["Stops spell suggestions everywhere, not only in battlegrounds or arenas, but keeps the display with the DPS strip and swing timer."] = "在所有地方停止法术建议（不仅是战场或竞技场），但保留显示框中的DPS条和攻击计时器。"
L["Shows an estimated parse percentile in the Stats window, based on this spec's benchmark numbers."] = "在统计窗口中显示根据此专精基准数据估算的解析百分位。"
L["Keeps your last fight's numbers on the DPS strip after combat ends instead of hiding it. Only applies when Show DPS/HPS is on."] = "战斗结束后在DPS条上保留上一场战斗的数值，而不是将其隐藏。仅在“显示 DPS/HPS”开启时生效。"
L["Shows how your DPS compares to your personal best: the difference in DPS on the DPS strip, +/- % in the Stats window."] = "显示你的DPS与个人最佳成绩的比较：DPS条上显示DPS差值，统计窗口中显示 +/- %。"
L["Shows your rotation efficiency score on the DPS strip and in the Stats window."] = "在DPS条和统计窗口中显示你的循环效率评分。"
L["When the DPS numbers start over. Each combat: every fight. Boss only: fights add up until a boss fight starts. Manual: only when you press Reset Now."] = "DPS数值何时重新开始统计。“每次战斗”：每场战斗。“仅首领”：数值持续累计，直到首领战开始。“手动”：仅在你点击“立即重置”时。"
L["Clears the DPS numbers now (in Manual mode also Blizzard's damage meter)."] = "立即清除DPS数值（手动模式下也会清除 Blizzard 的伤害统计）。"
L["Prints your last 10 fights to chat."] = "在聊天框输出你最近10场战斗。"
L["Dark box behind the DPS strip. 0 (default) = no box. Only applies when Show DPS/HPS is on."] = "DPS条后面的深色背景框。0（默认）= 无背景框。仅在“显示 DPS/HPS”开启时生效。"
L["Opacity of the floating Stats window."] = "浮动统计窗口的不透明度。"
L["Adds a player's gear score and item level to their tooltip when you hover them."] = "鼠标悬停在玩家身上时，在其鼠标提示中添加装备评分和物品等级。"
L["Rescans your gear and buffs and updates the boxes above."] = "重新扫描你的装备和增益，并更新上方的框。"
L["Saves your current settings as a profile with the name typed in the box (replaces a profile of that name) and makes it active."] = "将当前设置保存为以输入框中名称命名的配置文件（会替换同名配置文件），并将其设为当前配置。"
L["Loads the profile selected in the list. Double-clicking a profile does the same."] = "加载列表中选中的配置文件。双击配置文件效果相同。"
L["Deletes the selected profile, after you confirm. The Default profile can't be deleted."] = "确认后删除选中的配置文件。默认配置文件无法删除。"
L["Gives the selected profile the name typed in the box."] = "将选中的配置文件改为输入框中的名称。"
L["Copies the selected profile (or the active one) to a new profile with the name typed in the box."] = "将选中的配置文件（或当前配置文件）复制为以输入框中名称命名的新配置文件。"
L["When your detected spec changes, loads the profile you assigned to that spec with Use for this spec."] = "当检测到的专精变化时，加载你通过“用于此专精”指定给该专精的配置文件。"
L["Assigns the selected profile (or the active one) to your current spec."] = "将选中的配置文件（或当前配置文件）指定给你当前的专精。"
L["Removes the profile assigned to your current spec."] = "移除指定给你当前专精的配置文件。"
L["Puts the selected profile (or the active one) in the box as a text string you can copy and share. The active profile exports your current settings, including changes you have not saved."] = "将选中的配置文件（或当前配置文件）以文本字符串的形式放入输入框，方便复制和分享。当前配置文件会导出你现在的设置，包括尚未保存的更改。"
L["Saves the profile string pasted in the box as a profile, named by the name box or by the string itself."] = "将粘贴到输入框中的配置字符串保存为配置文件，名称取自名称框或字符串本身。"
L["While the talent frame is open, a green NEXT glow marks the next talent of your build, and the right spec tab and the Apply button are pointed out. Also prints a chat note when a point is free."] = "天赋面板打开时，绿色的“下一个”高亮会标出你方案中的下一个天赋，并指出正确的专精标签和“应用”按钮。有空余天赋点时也会在聊天框中提示。"
L["Makes the talent button on the micro menu glow while you have an unspent point for your build. Only applies when Glow the next talent in the talent frame is on."] = "当你有可用于方案的未分配天赋点时，让微型菜单上的天赋按钮发光。仅在“在天赋面板中高亮下一个天赋”开启时生效。"
L["Opens the Next Talent popup with the next talent of your build."] = "打开“下一个天赋”弹窗，显示你方案中的下一个天赋。"
L["Opens the build browser to pick another talent build for your spec."] = "打开方案浏览器，为你的专精选择其他天赋方案。"
L["Shows this spec's recommended talent build below."] = "在下方显示此专精的推荐天赋方案。"
L["Picks this spec's leveling build."] = "选择此专精的升级方案。"
L["Picks this spec's PvE build (dungeons and raids)."] = "选择此专精的PvE方案（地下城和团队副本）。"
L["Picks this spec's PvP build."] = "选择此专精的PvP方案。"
L["Cycles this spec's build type: Leveling, PvE, PvP."] = "切换该专精的天赋方案类型：升级、PvE、PvP。"
L["Picks which of this spec's talent builds the guide shows and follows."] = "选择指南显示并跟随的该专精天赋方案。"
L["Re-reads your talents and stops following a build started with Start Build."] = "重新读取你的天赋，并停止跟随通过“开始方案”开始的方案。"
L["Opens the game's talent frame."] = "打开游戏的天赋面板。"
L["Opens the game's macro window (/macro), where you drag the macros you created to your bars."] = "打开游戏的宏窗口（/macro），将你创建的宏拖到动作条上。"
L["Updates every macro you already created from this page to its latest version."] = "将你在此页面创建的所有宏更新为最新版本。"
L["Visibility"] = "可见性"
L["Suggestions"] = "建议"
L["Troubleshooting"] = "故障排除"
L["Hide name, reason and DPS strip"] = "隐藏名称、原因和DPS条"
L["Buff reminder text"] = "增益提醒文本"
L["List all missing buffs"] = "列出所有缺少的增益"
L["Suggest buffs & pets"] = "建议增益和宠物"
L["Glow the suggested spell"] = "建议法术发光"
L["Saved rotations"] = "已保存的循环"
L["Balance: remind you to be in Moonkin Form out of combat, and suggest shifting back into it after a caster-form heal in combat"] = "平衡：脱离战斗时提醒你保持枭兽形态，并在战斗中以施法者形态治疗后建议变回枭兽形态"
L["Feral, in groups only (solo, LazyGCore picks the form itself). Bear always suggests Bear Form, Cat never does. Auto: Bear when you are in Bear Form, the group made you its tank, you run a Bear build or your last shift was into Bear; otherwise Cat"] = "野性，仅限组队（单人时 LazyGCore 自行选择形态）。“熊”总是建议熊形态，“猫”从不建议。“自动”：当你处于熊形态、队伍将你设为坦克、你使用熊天赋方案或上次变形为熊时选择熊；否则选择猫"
L["In Bear Form, in combat, suggest Frenzied Regeneration below this health %. Needs Suggest defensives on (Combat page)"] = "在熊形态下的战斗中，生命值低于此%时建议狂暴回复。需开启“建议防御技能”（“战斗”页面）"
L["Suggest Hunter's Mark on elites, group targets, players and mobs above 60% health. Survival skips normal solo mobs it is about to melee, unless it has Expose Prey (which only procs on Marked targets)"] = "对精英、队伍目标、玩家以及生命值高于60%的怪物建议猎人印记。生存天赋会跳过即将进入近战的普通单人怪物，除非拥有暴露猎物（只对带有印记的目标触发）"
L["Out of combat, remind you to call your pet, revive it if it died, or feed it when it is not happy. Skipped if you have the Lone Wolf talent"] = "脱离战斗时，提醒你召唤宠物、在宠物死亡时复活它，或在它不高兴时喂食。拥有孤狼天赋时跳过"
L["Out of combat, remind you to put up your combat aspect: Aspect of the Hawk (Monkey before level 10); Survival uses Monkey until it learns Aspect of the Beast. Waits while Cheetah, Pack or Wild is on, and in combat warns when Cheetah or Pack is still on"] = "脱离战斗时，提醒你开启战斗守护：雄鹰守护（10级前为灵猴守护）；生存在学会野兽守护前使用灵猴守护。猎豹守护、豹群守护或野性守护开启时会等待，战斗中若猎豹守护或豹群守护仍开启则发出警告"
L["In combat, suggest Mend Pet when your pet drops below this % (out of combat it reminds you below 60%). Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your pet takes. Needs Suggest defensives on (Combat page)"] = "战斗中，宠物生命值低于此%时建议治疗宠物（脱离战斗时低于60%会提醒）。Forever 在战斗中隐藏宠物生命值：LazyGCore 会根据宠物受到的伤害和治疗进行估算。需开启“建议防御技能”（“战斗”页面）"
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 15% of your Intellect as spell damage for 15 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "奥术：对精英、首领、群体和玩家，在奥术愤怒和奥术飞弹之前先叠加此层数的奥术冲击。每层在第一次奥术冲击后的15秒内将你15%的智力转化为法术伤害，但会让下一次奥术冲击消耗更多法力（普通小怪总是只用一次奥术冲击）"
L["Fire with 3 points in Improved Scorch: keep this many Fire Vulnerability stacks up with Scorch on bosses, skull-marked targets and elites (solo or in a raid; never on players)"] = "火焰且强化灼烧3点：对首领、骷髅标记目标和精英用灼烧维持此层数的火焰易伤（单人或团队中；从不对玩家）"
L["Suggest Evocation when you run low on mana: out of combat below the Evocation Threshold, in combat once you can't afford your filler spell"] = "法力值不足时建议唤醒：脱离战斗时低于唤醒阈值，战斗中则在你无法负担填充法术时"
L["In combat, suggest a mana gem when you run low on mana, before Evocation (needs Suggest defensives and Suggest cooldowns on, Combat page). Out of combat, remind you to conjure one when your bags have none"] = "战斗中法力值不足时，在唤醒之前建议使用法力宝石（需开启“建议防御技能”和“建议冷却技能”，“战斗”页面）。脱离战斗时，背包中没有法力宝石会提醒你制造一个"
L["Suggest Evocation when mana is below this %. Out of combat only: Forever hides your mana in combat, so there Evocation is suggested once you can't afford your filler spell"] = "法力值低于此%时建议唤醒。仅限脱离战斗：Forever 在战斗中隐藏你的法力值，因此战斗中会在你无法负担填充法术时建议唤醒"
L["Suggest Consecration in melee range when mana allows, mostly on packs and elites. Applies to every spec (Holy only when solo)"] = "在法力允许时于近战范围内建议奉献，主要针对成群敌人和精英。适用于所有专精（神圣仅限单人时）"
L["Protection: on keeps Holy Shield up whenever you are in melee. Off: only against elites or when your health is below 50%"] = "防护：开启时只要处于近战就维持神圣之盾。关闭：仅对精英或你的生命值低于50%时"
L["Out of combat, remind you to put your blessing on yourself when it is missing or has under 1 minute left. Holy in a group: also Blessing of Kings on the ally you heal"] = "脱离战斗时，当你身上缺少祝福或剩余不到1分钟时提醒你给自己施放。神圣组队时：也会为你治疗的队友施放王者祝福"
L["The blessing the reminder keeps on you (needs Blessing Reminder on). Auto: Wisdom for Holy, Kings for Protection, Might otherwise. Might is used until the chosen one is learned"] = "提醒功能为你维持的祝福（需开启“祝福提醒”）。“自动”：神圣用智慧，防护用王者，其余用力量。在学会所选祝福前使用力量祝福"
L["Auto: the new Shadow Word: Pain lands right as the old one ends (recasting early throws away its remaining ticks). Or refresh when this many seconds remain. Applies to every spec while it deals damage"] = "自动：新的暗言术：痛在旧的刚结束时生效（提前重新施放会浪费剩余的跳数）。或者剩余此秒数时刷新。适用于所有正在输出伤害的专精"
L["Only suggest Shadow Word: Death while your own health is above this % (it hurts you if the target survives)"] = "仅在你自身生命值高于此%时建议暗言术：灭（若目标未死亡会对你造成伤害）"
L["Never suggest Fade. When off, Fade is suggested in a group as soon as you pull threat"] = "从不建议渐隐术。关闭时，在队伍中一旦获得仇恨就会建议渐隐术"
L["In combat, suggest Mind Blast every time it comes off cooldown. Off: the normal priority decides, and normal mobs often get your wand to save mana"] = "战斗中，心灵震爆每次冷却结束都建议使用。关闭：由正常优先级决定，普通怪物通常会建议使用魔杖以节省法力"
L["Combo points to build before Eviscerate. Auto: 5 with talents (4 before), and 4 on normal mobs while questing (3 below level 20) so they die sooner. A target about to die gets Eviscerate from 2 points"] = "刺骨前积攒的连击点数。“自动”：有天赋时5点（之前为4点），对做任务时的普通怪物为4点（20级以下为3点）以便更快击杀。即将死亡的目标2点即可刺骨"
L["Keep Slice and Dice up (from 2 combo points, 4 for Combat) on targets above 25% health. Leveling and Combat skip normal mobs while questing; Assassination and Subtlety skip players. Off: never suggest it"] = "对生命值高于25%的目标维持切割（2个连击点起，战斗天赋4个起）。升级和战斗天赋跳过做任务时的普通怪物；奇袭和敏锐跳过玩家。关闭：从不建议切割"
L["Auto: each spec's own choice (Assassination: Rupture on elites, Subtlety: on elites, groups and players, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "“自动”：各专精自行选择（奇袭：对精英使用割裂；敏锐：对精英、群体和玩家使用；战斗和升级：只用刺骨）。“割裂”：目标生命值高于35%且没有割裂时优先割裂。“刺骨”：从不使用割裂"
L["Assassination and Combat: in a group, suggest Vanish against an elite (while you don't hold threat) so you can use a stealth opener again. Subtlety has its own Vanish rule"] = "奇袭和战斗：组队时对精英建议消失（在你没有仇恨时），以便再次使用潜行起手技能。敏锐有自己的消失规则"
L["Suggest your damage and buff totems (Searing, Magma, Strength of Earth, water totems, totem sets), mostly on elites, groups and players; Magma Totem on packs. Off: only utility totems such as Stoneclaw, Grounding, Tremor and Mana Tide are still suggested"] = "建议你的伤害和增益图腾（灼热图腾、熔岩图腾、大地之力图腾、水系图腾、图腾组），主要针对精英、群体和玩家；熔岩图腾用于成群敌人。关闭：只建议石爪图腾、根基图腾、战栗图腾和法力之潮图腾等功能性图腾"
L["Enhancement and Restoration, once you have Water Shield: remind you to refresh it out of combat when under 1 minute, and recast it in combat when it drops"] = "增强和恢复，学会水之护盾后：脱离战斗时剩余不到1分钟提醒你刷新，战斗中消失时重新施放"
L["Restoration: suggest Chain Heal when at least this many group members are below 80% health. In combat Forever hides group health: LazyGCore estimates it from the damage and heals they take"] = "恢复：至少此数量的队友生命值低于80%时建议治疗链。Forever 在战斗中隐藏队伍生命值：LazyGCore 根据他们受到的伤害和治疗进行估算"
L["Suggest Life Tap when you run low on mana and your health is above 50%. Between pulls it also reminds you below 60% mana when your health is above 75%"] = "法力值不足且生命值高于50%时建议生命分流。在两次开怪之间，法力值低于60%且生命值高于75%时也会提醒"
L["Suggest Life Tap when mana is below this % (health above 50%). Forever hides your mana in combat, so there Life Tap is suggested once you can't afford Shadow Bolt. Between pulls a separate reminder appears below 60% mana"] = "法力值低于此%时建议生命分流（生命值高于50%）。Forever 在战斗中隐藏你的法力值，因此战斗中会在你无法负担暗影箭时建议生命分流。两次开怪之间，法力值低于60%时会出现单独的提醒"
L["Solo, in combat: suggest Health Funnel when your demon drops below this % and your own health is above 55%. Forever hides pet health in combat: LazyGCore estimates it from the damage and heals your demon takes. Needs Suggest defensives on (Combat page)"] = "单人战斗中：当你的恶魔生命值低于此%且你自身生命值高于55%时建议生命通道。Forever 在战斗中隐藏宠物生命值：LazyGCore 根据恶魔受到的伤害和治疗进行估算。需开启“建议防御技能”（“战斗”页面）"
L["Your one Curse per target. Auto: Curse of the Elements on elites and in groups (Curse of Weakness on elites before you learn it); on players Curse of Tongues for casters, Curse of Exhaustion or Weakness for the rest. A fixed curse goes on elites, group targets and players; None leaves the Curse to another Warlock (Banes still apply)"] = "每个目标只能有一个诅咒。“自动”：对精英和组队时使用元素诅咒（学会前对精英使用虚弱诅咒）；对玩家，施法者用语言诅咒，其他用疲劳诅咒或虚弱诅咒。固定的诅咒用于精英、队伍目标和玩家；“无”将诅咒留给其他术士（灾祸仍会施放）"
L["Destruction only. Also picks your weapon stone (Firestone with Incinerate, Spellstone with Shadow Bolt) and the demon you sacrifice (Sayaad or Imp). Auto: Incinerate if you have the Incinerate talent and 5 points in Shadow and Flame, otherwise Shadow Bolt"] = "仅限毁灭。同时决定你的武器石（烧尽用火焰石，暗影箭用法术石）以及要牺牲的恶魔（萨亚德或小鬼）。“自动”：拥有烧尽天赋且影与焰5点时使用烧尽，否则使用暗影箭"
L["Protection: build Sunder Armor to this many stacks on elites and in dungeons and raids, and refresh it before it drops (normal mobs while questing get 2)"] = "防护：对精英以及在地下城和团队中将破甲攻击叠加到此层数，并在消失前刷新（做任务时的普通怪物叠2层）"
L["Use Heroic Strike when rage is above this (Auto = per spec: 30 leveling, 60 Arms/Fury, 45 Protection). In combat Rage is hidden: LazyGCore checks you could still afford a spell of that cost (30+: Mortal Strike / Bloodthirst, 25: Intimidating Shout / Whirlwind, 20: Cleave / Thunder Clap, 15 or less: Heroic Strike)"] = "怒气高于此值时使用英勇打击（自动 = 按专精：升级30，武器/狂怒60，防护45）。战斗中怒气被隐藏：LazyGCore 会检查你是否仍能负担该消耗的技能（30以上：致死打击/嗜血，25：破胆怒吼/旋风斩，20：顺劈斩/雷霆一击，15或以下：英勇打击）"
L["Protection: on suggests Shield Block whenever you are tanking in melee. Off: only against elites or when your health is below 50%"] = "防护：开启时只要你在近战中坦克就建议盾牌格挡。关闭：仅对精英或你的生命值低于50%时"
L["Suggest Battle Shout whenever it is missing (out of combat also when under 10 seconds remain)"] = "缺少战斗怒吼时建议施放（脱离战斗时剩余不到10秒也会建议）"

-- sim pass: raid-only utility options
L["Faerie Fire in raids"] = "团队中使用精灵之火"
L["Balance: keep Faerie Fire's armor debuff on the boss in raids. It only helps physical attackers and costs you a GCD and mana, so leave it off unless your raid has no other armor debuff. Groups of 5 always get it"] = "平衡：在团队中保持首领身上的精灵之火护甲减益。它只对物理攻击者有帮助，并消耗一个公共冷却和法力，除非团队没有其他护甲减益，否则请保持关闭。5人小队中总是会建议"
L["Vampiric Embrace in raids"] = "团队中使用吸血鬼的拥抱"
L["Shadow: keep Vampiric Embrace on the boss in raids so your Shadow damage heals your party. It does no damage and costs a GCD every 30 seconds. In groups of 5 and in battlegrounds it is always suggested; solo only while your health is below 60%"] = "暗影：在团队中保持首领身上的吸血鬼的拥抱，让你的暗影伤害治疗小队。它不造成伤害，每30秒消耗一个公共冷却。5人小队和战场中总是会建议；单人时仅在你的生命值低于60%时建议"
L["Shows the colored ring around the main icon. The ring is also the swing timer, so hiding it also hides that swing timer (the swing timer bars stay visible)."] = "显示主图标周围的彩色圆环。该圆环同时也是攻击计时器，隐藏它也会隐藏该攻击计时器（攻击计时条仍会显示）。"
L["Hide/show the spell name, reason and DPS strip (and the queue in the stacked layout)"] = "隐藏/显示法术名称、原因和DPS条（堆叠布局中还包括队列）"

