-- fix_talentrange: gear score label (GS) and auto attack reasons
L["Show your gear score (GS) under the keybind on the rotation icon. GS rates your equipped gear by item level and quality; the colour is its tier (green, blue, purple). Only shown at level 60."] = "在循环图标的快捷键下方显示你的 GearScore（GS）。GS 根据已装备物品的物品等级和品质评分，颜色表示其档次（绿、蓝、紫）。仅在60级时显示。"
