-- fix_macros: per-character class macros, Account section, move to character
L["Account (all characters)"] = "账号（所有角色）"
L["Will be saved to General (account) macros"] = "将保存到通用（账号）宏"
L["Will be saved to Character macros"] = "将保存到角色专用宏"
L["All your characters see this copy. Move it to keep it on this character only."] = "你的所有角色都能看到这个副本。移动它以仅保留在此角色上。"
L["Move to this character"] = "移到此角色"
L["Moves this macro from the General (account) macros to this character's macros. Other characters lose this macro; put it back on your action bar."] = "将此宏从通用（账号）宏移到此角色的宏。其他角色将失去此宏；请把它重新放到动作条上。"
L["(account macro)"] = "（账号宏）"
L["%s moved to this character's macros. Put it back on your action bar."] = "%s已移到此角色的宏。请把它重新放到动作条上。"
L["Could not move %s; nothing was deleted."] = "无法移动%s；没有删除任何内容。"
L["Your General (account) macros are full (%d). Delete one in the macro window (/macro) first."] = "你的通用（账号）宏已满（%d）。请先在宏窗口（/macro）中删除一个。"
L["Your character macros are full (%d). Delete one in the macro window (/macro) first."] = "你的角色专用宏已满（%d）。请先在宏窗口（/macro）中删除一个。"
L["Use your top trinket (slot 13)"] = "使用上方饰品（栏位13）"
L["Use your bottom trinket (slot 14)"] = "使用下方饰品（栏位14）"
L["Focus your mouseover, else your target"] = "将鼠标悬停目标设为焦点，否则设为当前目标"
L["Clear your focus"] = "清除焦点"
L["Target what your focus is targeting"] = "选中你焦点的目标"
L["Put a Skull on your target (press again to remove it)"] = "给你的目标标记骷髅（再按一次取消）"
L["Start a ready check (group leader or raid assistant)"] = "发起就位确认（队长或团队助理）"
L["Show or hide the LazyGCore rotation display"] = "显示或隐藏LazyGCore循环显示"
L["Reload the user interface"] = "重新载入界面"


-- Growth features (Group Sync, share build, welcome tour, version notice)
L["A newer LazyGCore is out (%s) - update on CurseForge."] = "LazyGCore 有新版本（%s），请在 CurseForge 上更新。"
L["Group Sync is off (Combat settings)."] = "队伍同步已关闭（战斗设置）。"
L["You are not in a group."] = "你不在队伍中。"
L["No other LazyGCore users in your group yet."] = "你的队伍中还没有其他 LazyGCore 用户。"
L["LazyGCore users in your group"] = "队伍中的 LazyGCore 用户"
L["newer"] = "较新"
L["List the LazyGCore users in your group and their versions"] = "列出队伍中的 LazyGCore 用户及其版本"
L["Group Sync"] = "队伍同步"
L["LazyGCore users in your party or raid quietly share their addon version, interrupt and big cooldowns over the hidden addon channel: the KICK! box shows who kicks next, and group cooldowns show under the display. Nothing is posted to chat and players without LazyGCore see nothing. Never sent while the game restricts addon messages (boss encounters, PvP)."] = "队伍或团队中的 LazyGCore 用户通过隐藏的插件频道悄悄共享插件版本、打断技能和大型冷却：打断！框会显示下一个由谁打断，队伍冷却会显示在显示框下方。不会在聊天中发送任何内容，没有 LazyGCore 的玩家什么也看不到。游戏限制插件消息时（首领战、PvP）从不发送。"
L["Show group cooldowns"] = "显示队伍冷却"
L["Shows a small line under the display when a LazyGCore user in your group uses a big defensive or raid cooldown (Shield Wall, Divine Shield, Innervate, Mana Tide Totem...). Hidden when you are solo. Only applies when Group Sync is on."] = "队伍中的 LazyGCore 用户使用大型防御或团队冷却（盾墙、圣盾术、激活、法力之潮图腾……）时，在显示框下方显示一小行文字。单人时隐藏。仅在队伍同步开启时生效。"
L["New version notice"] = "新版本提示"
L["Prints one line in your own chat window, once per session, when a group member runs a newer LazyGCore. Nobody else sees it."] = "队伍成员使用较新版本的 LazyGCore 时，每次登录只在你自己的聊天窗口显示一行。其他人看不到。"
L["You kick next"] = "下一个由你打断"
L["%s kicks next"] = "下一个由 %s 打断"
L["The welcome tour opens after combat."] = "欢迎导览将在战斗结束后打开。"
L["Replay the short welcome tour"] = "重新播放简短的欢迎导览"
L["Welcome"] = "欢迎"
L["Your rotation display"] = "你的输出循环显示"
L["/lazygcore"] = "/lazygcore"
L["This is LazyGCore's display: the big icon is the ability to use next, PREV shows your last casts and NEXT what comes after. A grey icon is out of range or short on mana, the small icon beside it is a cooldown ready to use, and the LazyGCore logo means nothing to press. It shows in combat and when you target an enemy. Drag it to move it."] = "这是 LazyGCore 的显示框：大图标是下一个要使用的技能，“上一”显示你最近施放的技能，“下一”显示之后的技能。灰色图标表示超出距离或法力不足，旁边的小图标是可用的冷却技能，LazyGCore 标志表示现在没有需要按的技能。它会在战斗中以及你选中敌人时出现。拖动即可移动它。"
L["The Talents page shows the next talent of your build and lets you pick another build. While the talent frame is open, your next talent glows."] = "天赋页面会显示你的方案中的下一个天赋，也可以选择其他方案。天赋界面打开时，你的下一个天赋会发光。"
L["Skip tour"] = "跳过导览"
L["Next"] = "下一步"
L["Goes to the next step of the tour."] = "进入导览的下一步。"
L["Done"] = "完成"
L["Step %d of %d"] = "第 %d 步，共 %d 步"
L["Enjoying LazyGCore? A rating on CurseForge helps other players find it."] = "喜欢 LazyGCore 吗？在 CurseForge 上评分可以帮助其他玩家找到它。"
L["Click the link, then press Ctrl+C to copy it."] = "点击链接，然后按 Ctrl+C 复制。"
L["CurseForge"] = "CurseForge"
L["Say"] = "说"
L["Party"] = "小队"
L["Raid"] = "团队"
L["Guild"] = "公会"
L["Whisper target"] = "密语目标"
L["Whisper"] = "密语"
L["no player targeted"] = "未选中玩家"
L["leveling build"] = "升级方案"
L["PvE build"] = "PvE方案"
L["PvP build"] = "PvP方案"
L["You are not in a raid."] = "你不在团队中。"
L["You are not in a guild."] = "你不在公会中。"
L["Target a player to whisper your build."] = "选中一名玩家才能密语你的方案。"
L["Chat is restricted right now. Try again after the fight."] = "聊天目前受到限制。请在战斗结束后重试。"
L["Wait a few seconds before sharing again."] = "请等待几秒后再分享。"
L["Could not post the build."] = "无法发送方案。"
L["No talent build to share for this spec."] = "此专精没有可分享的天赋方案。"
L["Posts to: %s"] = "发送到：%s"
L["Share build"] = "分享方案"
L["Post to"] = "发送到"
L["Where Share build posts your build: Say, Party, Raid, Guild, or a whisper to the player you target."] = "“分享方案”发送你的方案的位置：说、小队、团队、公会，或密语你选中的玩家。"

