-- Share LazyGCore tab, chat channels, contact links, welcome tour (UI/ShareLazyGCore, UI/Welcome)
L["Other LazyGCore users: %d in your group, %d in your guild"] = "其他 LazyGCore 用户：队伍中 %d 人，公会中 %d 人"
L["Turn on Share gear score with LazyGCore users (Parsing tab) to see how many players around you use LazyGCore."] = "开启“与 LazyGCore 用户共享装备评分”（解析标签页），即可查看你身边有多少玩家在用 LazyGCore。"
L["Follow LazyGCore"] = "关注 LazyGCore"
L["Enjoying LazyGCore? Follow it and add it to your favorites on CurseForge: you hear about every update first, and it helps other players find it."] = "喜欢 LazyGCore 吗？在 CurseForge 上关注并收藏它：每次更新你都会第一时间知道，也能帮助其他玩家找到它。"
L["Share LazyGCore"] = "分享 LazyGCore"
L["Know someone who would like LazyGCore? Share it in one click. When your group runs LazyGCore together, Group Sync shows who kicks next."] = "认识会喜欢 LazyGCore 的朋友吗？一键分享。队伍里都用 LazyGCore 时，队伍同步会显示下一个打断的人。"
L["I use LazyGCore Forever for my rotation and talents: it shows what to press next. Free on CurseForge: %s - get it too and Group Sync shows who kicks next!"] = "我用 LazyGCore Forever 来打循环和点天赋：它会提示下一个该按的技能。CurseForge 免费下载：%s 一起装上，队伍同步就能显示下一个打断的人！"
L["Posts ONE chat line telling your friends about LazyGCore Forever, with the CurseForge link, to the channel picked in Post to. Sent only when you click, never automatically."] = "向“发送到”中选择的频道发送一行聊天消息，向朋友介绍 LazyGCore Forever 并附上 CurseForge 链接。仅在你点击时发送，绝不自动发送。"
L["Where Share LazyGCore and Share build post: Say, Party, Raid, Guild, a whisper to the player you target, or a chat channel you have joined (Trade, General, LookingForGroup ...). Public channels: one share a minute."] = "“分享 LazyGCore”和“分享方案”的发送位置：说、小队、团队、公会、密语你选中的玩家，或你已加入的聊天频道（交易、综合、寻求组队……）。公共频道每分钟最多一次。"
L["Target a player to whisper the link."] = "选中一名玩家才能密语链接。"
L["Could not post the message."] = "无法发送消息。"
L["Usage: /lazygcore share [say / party / raid / guild / whisper / trade / general / channel number]"] = "用法：/lazygcore share [say / party / raid / guild / whisper / trade / general / 频道编号]"
L["Tell your friends about LazyGCore: posts one chat line (say, party, raid, guild, whisper or a chat channel such as trade)"] = "向朋友介绍 LazyGCore：发送一行聊天消息（说、小队、团队、公会、密语或交易等聊天频道）"
L["You can also type /lazygcore share, or /lazygcore share trade, general, guild, party ..."] = "也可以输入 /lazygcore share，或 /lazygcore share trade、general、guild、party ……"
L["Suggestions & bug reports"] = "建议与问题反馈"
L["Have an idea, or did LazyGCore suggest something wrong? Tell me on CurseForge: leave a comment on the LazyGCore page or message me on my profile. Include your class, spec and what /lazygcore status prints."] = "有想法，或者 LazyGCore 的提示不对？请在 CurseForge 上告诉我：在 LazyGCore 页面留言，或通过我的个人主页给我发消息。请附上你的职业、专精以及 /lazygcore status 的输出。"
L["Comments"] = "评论"
L["Comments on the LazyGCore Forever page. Click the link, then press Ctrl+C to copy it."] = "LazyGCore Forever 页面的评论区。点击链接，然后按 Ctrl+C 复制。"
L["The author's CurseForge profile. Click the link, then press Ctrl+C to copy it."] = "作者的 CurseForge 个人主页。点击链接，然后按 Ctrl+C 复制。"
L["Welcome tour"] = "欢迎导览"
L["A short tour of the display and every settings tab."] = "简短介绍显示框和每个设置标签页。"
L["Replay The Welcome Tour"] = "重新播放欢迎导览"
L["Shows the welcome tour again: the display and every settings tab, one step at a time."] = "再次显示欢迎导览：显示框和每个设置标签页，一步一步介绍。"
L["not joined"] = "未加入"
L["You are not in the %s channel right now (Trade only works in cities)."] = "你目前不在 %s 频道中（交易频道只在主城可用）。"
L["Public channels: one share a minute. Try again shortly."] = "公共频道每分钟只能分享一次。请稍后再试。"
L["Closes the tour. You can replay it from the Share LazyGCore tab or with /lazygcore tour."] = "关闭导览。可在“分享 LazyGCore”标签页或用 /lazygcore tour 重新播放。"
L["Goes back to the previous step of the tour."] = "返回导览的上一步。"
L["Turn LazyGCore on or off, lock the display, pick the rotation engine and spec, choose when the display shows, and change its theme, skin and size. Hover over any option to see what it does."] = "开启或关闭 LazyGCore、锁定显示框、选择推荐引擎和专精、设置显示时机，并修改主题、皮肤和大小。将鼠标悬停在任意选项上即可查看说明。"
L["Everything on the display: the main and cooldown icons, spell history and timeline, the action bar glow and the swing timer."] = "显示框的一切：主图标和冷却图标、法术历史和时间轴、动作条高亮以及攻击计时条。"
L["What LazyGCore suggests (AoE, defensives, buffs and pets), the KICK!, DEFENSIVE! and PURGE alerts with their sounds, and Group Sync with your group."] = "LazyGCore 的提示内容（范围、减伤、增益和宠物）、KICK!、DEFENSIVE! 和 PURGE 警报及其音效，以及与队伍的队伍同步。"
L["Options for your own class, such as the Warlock curse, Rogue finishers or Mage mana gems."] = "你自己职业的选项，例如术士诅咒、盗贼终结技或法师法力宝石。"
L["Ready-made macros for your class and spec (PvE and PvP), plus account macros for all your characters. One click creates them."] = "适用于你的职业和专精（PvE 和 PvP）的现成宏，以及所有角色通用的账号宏。一键即可创建。"
L["Your DPS and HPS strip, the Stats window, GearScore, consumables, parse readiness and who else uses LazyGCore."] = "你的 DPS 和 HPS 条、统计窗口、GearScore、消耗品、打分准备情况，以及还有谁在使用 LazyGCore。"
L["Build your own rotation, exclude spells you never want suggested, and turn LazyGCore off in chosen instances."] = "创建你自己的循环，排除你不想被提示的法术，并在选定的副本中关闭 LazyGCore。"
L["Update speed, troubleshooting tools and Reset all settings."] = "更新速度、故障排查工具以及重置所有设置。"
L["Save, load, copy and share your settings, or switch profiles automatically per spec."] = "保存、加载、复制和分享你的设置，或按专精自动切换配置。"
L["LazyGCore speaks six languages: English, German, Spanish, French, Japanese and Simplified Chinese. Pick one here, or keep Auto."] = "LazyGCore 支持六种语言：英语、德语、西班牙语、法语、日语和简体中文。在这里选择，或保持自动。"
L["What LazyGCore is and how it reads the game on Forever."] = "LazyGCore 是什么，以及它如何在 Forever 中读取游戏信息。"
L["Type /lazygcore for the settings, /lazygcore help for every command. Replay this tour any time from the Share LazyGCore tab."] = "输入 /lazygcore 打开设置，/lazygcore help 查看所有命令。随时可在“分享 LazyGCore”标签页重新播放本导览。"

-- LazyGCore links (ShareLink)
L["%s Click it with LazyGCore Forever to use it - free on CurseForge: %s"] = "%s 用 LazyGCore Forever 点击即可使用 - CurseForge 免费下载：%s"
L["%s %s rotation"] = "%s%s循环"
L["%s %s %s"] = "%s%s%s"
L["Before %s's rotation"] = "使用 %s 的循环之前"
L["No rotation to share for this spec."] = "此专精没有可分享的循环。"
L["Share rotation"] = "分享循环"
L["Posts a LazyGCore link to the build your Talent Guide follows, to the channel picked in Post to. Players with LazyGCore click it to follow the same build; everyone else sees where to get LazyGCore. Sent only when you click."] = "将你的天赋指南所遵循方案的 LazyGCore 链接发送到“发送到”中选择的频道。装有 LazyGCore 的玩家点击即可遵循同一方案；其他人会看到在哪里获取 LazyGCore。仅在你点击时发送。"
L["Posts a LazyGCore link to your rotation for this spec (your custom list, or LazyGCore's default when you have none), to the channel picked in Post to. Players with LazyGCore click it to use it; everyone else sees where to get LazyGCore. Sent only when you click."] = "将你此专精循环（你的自定义列表，没有则为 LazyGCore 默认循环）的 LazyGCore 链接发送到“发送到”中选择的频道。装有 LazyGCore 的玩家点击即可使用；其他人会看到在哪里获取 LazyGCore。仅在你点击时发送。"
L["That is your own share."] = "这是你自己的分享。"
L["LazyGCore links open after combat."] = "LazyGCore 链接要在战斗结束后才能打开。"
L["LazyGCore can't send right now (combat, a boss fight or PvP). Try again in a moment."] = "LazyGCore 目前无法发送（战斗中、首领战或 PvP）。请稍后再试。"
L["Already asking for that share..."] = "已经在请求这个分享了……"
L["That LazyGCore link doesn't work."] = "这个 LazyGCore 链接无效。"
L["Asking %s for their LazyGCore share..."] = "正在向 %s 请求 LazyGCore 分享……"
L["%s didn't answer. They must be online, and a share lasts 2 hours (or until they reload)."] = "%s 没有回应。对方必须在线，且分享在 2 小时内（或对方重载界面前）有效。"
L["%s's share has expired. Ask them to share it again."] = "%s 的分享已过期。请让对方重新分享。"
L["%s shared it for another class: it only works for that class."] = "%s 分享的是另一个职业的内容：只适用于该职业。"
L["%s's share is for a spec LazyGCore doesn't know here."] = "%s 的分享属于此处 LazyGCore 不认识的专精。"
L["%s's build isn't in your LazyGCore version. Update LazyGCore and try again."] = "你的 LazyGCore 版本中没有 %s 的方案。请更新 LazyGCore 后重试。"
L["%s's rotation has nothing your LazyGCore can use."] = "%s 的循环中没有你的 LazyGCore 能使用的内容。"
L["%s's share couldn't be read."] = "无法读取 %s 的分享。"
L["%s shared a %s rotation (%d spells: %s).\n\nUse it as your custom rotation? Your current list is kept as a saved rotation."] = "%s 分享了一个%s循环（%d 个法术：%s）。\n\n将其用作你的自定义循环吗？你当前的列表会保存为已存循环。"
L["Using %s's %s rotation. Change it any time on the Competitive tab."] = "正在使用 %s 的%s循环。可随时在“竞技”标签页中修改。"
L["Use it"] = "使用"
L["%s shared a %s build: %s.\n\nFollow it in your Talent Guide?"] = "%s 分享了一个%s方案：%s。\n\n要在天赋指南中遵循它吗？"
L["Your Talent Guide now follows %s's %s build."] = "你的天赋指南现在遵循 %s 的%s方案。"
L["Follow it"] = "遵循"
L["Share your rotation and build"] = "分享你的循环和方案"
L["Posts a LazyGCore link to the same channel. Players with LazyGCore click it to use your rotation or follow your talent build; everyone else sees where to get LazyGCore."] = "向同一频道发送 LazyGCore 链接。装有 LazyGCore 的玩家点击即可使用你的循环或遵循你的天赋方案；其他人会看到在哪里获取 LazyGCore。"
L["Scan with your phone to open LazyGCore Forever on CurseForge."] = "用手机扫描即可在 CurseForge 打开 LazyGCore Forever。"
L["Point your phone's camera at the code to open LazyGCore Forever on CurseForge."] = "将手机摄像头对准二维码，即可在 CurseForge 打开 LazyGCore Forever。"
L["QR code"] = "二维码"
L["Start here: share LazyGCore with friends in one click (party, guild, whisper or a channel like Trade), share your rotation or talent build as a LazyGCore link, send me suggestions or bug reports, and replay this tour."] = "从这里开始：一键把 LazyGCore 分享给朋友（小队、公会、密语或交易等频道），以 LazyGCore 链接分享你的循环或天赋方案，向我提交建议或问题，以及重新播放本导览。"

LazyGCore.Locale:RegisterLocale("zhCN", L)

-- 1.0.7 (16 Oct beta build)
L["Arcane Wrath"] = "奥术愤怒"
L["Presence of Mind: instant 3.5s Arcane Wrath."] = "气定神闲：瞬发3.5秒的奥术愤怒。"
L["Your hardest hit: scales with your maximum mana (6s cooldown)."] = "你伤害最高的法术：随最大法力值提升（6秒冷却）。"
L["Winter's Chill: +40% Cone of Cold damage per stack."] = "深冬之寒：每层使冰锥术伤害提高40%。"
L["15s: faster Lightning Bolt and Lava Burst, Chain Lightning without a cooldown."] = "15秒：闪电箭和熔岩爆裂施法更快，闪电链无冷却。"
L["Elemental Mastery: no cooldown on Chain Lightning."] = "元素掌握：闪电链无冷却。"

-- 1.0.7 (16 Oct beta build)
L["Nothing to press right now - keep attacking."] = "现在没有需要按的技能 - 继续攻击。"
L["Enemy nameplates are off, so LazyGCore can't count the enemies around you and won't suggest AoE spells. Press V or type /lazygcore nameplates to turn them on."] = "敌方姓名板已关闭，LazyGCore 无法统计你周围的敌人，因此不会建议范围技能。按 V 或输入 /lazygcore nameplates 开启。"

-- 1.0.7 (16 Oct beta build)
L["Type /lazygcore reset confirm to reset all settings and reload the UI."] = "输入 /lazygcore reset confirm 以重置所有设置并重新载入界面。"

-- 1.0.7 (16 Oct beta build)
L["Use it on your weapon."] = "对你的武器使用它。"

-- 1.0.7 (16 Oct beta build)
L["Before Demonic Pact: Searing Pain out-damages Shadow Bolt."] = "学会恶魔契约之前：灼热之痛的伤害高于暗影箭。"
L["Questing: free damage while you nuke."] = "做任务时：在你输出时提供免费伤害。"

-- 1.0.7 (16 Oct beta build)
L["Can't change that in combat."] = "战斗中无法更改。"
L["Enemy nameplates are on: LazyGCore can count the enemies around you for AoE."] = "敌方姓名板已开启：LazyGCore 可以统计你周围的敌人以建议范围技能。"
L["Turn on enemy nameplates (LazyGCore counts nearby enemies from them for AoE suggestions)"] = "开启敌方姓名板（LazyGCore 据此统计附近敌人以建议范围技能）"
L["Automatic AoE threshold"] = "自动范围阈值"
L["Uses the best number of enemies for your spec, worked out by simulation (for example 2 for cleave specs). Turn it off to set your own number below. Only applies when Enable AoE suggestions is on."] = "使用通过模拟得出的最适合你专精的敌人数量（例如顺劈专精为2）。关闭后可在下方自行设置。仅在“启用AoE建议”开启时生效。"

-- 1.0.7 (16 Oct beta build)
L["Sunder Armor as DPS"] = "输出时使用破甲攻击"
L["Arms and Fury: stack Sunder Armor to 5 against elites and in 5-player groups when nobody else applies it (a big damage gain). Leave it off when a tank or another warrior sunders. Never in raids"] = "武器和狂怒：没有其他人施放时，对精英和5人小队中把破甲攻击叠到5层（大幅提升伤害）。有坦克或其他战士施放时请关闭。团队中从不使用"
L["Nobody else sunders: armor shred is worth more than your next hit."] = "没有其他人破甲：降低护甲比你的下一击更有价值。"

-- 1.0.7 (16 Oct beta build)
L["Improved Scorch: fast crits feed Heating Up."] = "强化灼烧：快速暴击为升温充能。"

-- 1.0.7 (16 Oct beta build)
L["Group: instant, shares Aimed Shot's cooldown."] = "小队：瞬发，与瞄准射击共享冷却。"

-- 1.0.8
L["Rotation for"] = "输出循环用于"
L["Automatic"] = "自动"
L["Open world"] = "野外"
L["Dungeon"] = "地下城"
L["Usage: /lazygcore content auto | world | dungeon | raid"] = "用法：/lazygcore content auto | world | dungeon | raid"
L["Show or set the content the rotation is for: auto, world (questing), dungeon or raid"] = "显示或设置输出循环针对的内容：auto、world（任务）、dungeon、raid"
L["Which rotation to use (this character). Automatic: the open-world questing rotation outside instances, also when you quest in a party, the dungeon rotation in 5-player dungeons and the raid rotation in raids. Pick one to always use it. Also /lazygcore content."] = "使用哪套输出循环（此角色）。自动：副本外使用野外任务循环（组队做任务时也是），5人地下城使用地下城循环，团队副本使用团队循环。选择一项则始终使用它。也可用 /lazygcore content。"

-- 1.0.8
L["Out of mana: drink a mana potion."] = "法力耗尽：喝一瓶法力药水。"
L["Low health: drink a healing potion."] = "生命值低：喝一瓶治疗药水。"
L["Potions"] = "药水"
L["Shows a mana potion on the cooldown icon once a fight has run you out of mana, and a healing potion below 35% health (the best potion in your bags, when its cooldown is ready)."] = "一场战斗让你法力耗尽后，在冷却图标上显示法力药水；生命值低于35%时显示治疗药水（背包中最好的药水，冷却就绪时）。"
L["Your pet is not happy: feed it for full damage."] = "你的宠物不高兴：喂食它以造成全额伤害。"

-- 1.0.8
L["Feed Pet"] = "喂养宠物"

-- 1.0.9
L["Playstyle"] = "打法风格"
L["Efficient"] = "节省"
L["Balanced"] = "均衡"
L["Max damage"] = "最大伤害"
L["Questing solo"] = "单人做任务"
L["Questing in a group"] = "组队做任务"
L["Usage: /lazygcore style auto | efficient | balanced | max"] = "用法：/lazygcore style auto | efficient | balanced | max"
L["Show or set the playstyle: auto, efficient (save mana and health), balanced or max (most damage)"] = "显示或设置打法风格：auto、efficient（节省法力和生命）、balanced 或 max（最大伤害）"
L["How hard to push (this character). Efficient: saves mana and health - fewer breaks to drink and eat while questing, more mana left after each pull in groups. Balanced: the fastest leveling counting rest, and steady damage with a mana reserve in groups. Max damage: the most damage now - every mob dies as fast as possible, best for raid bosses and when a healer keeps you up. Automatic: Balanced while questing and in dungeons, Max damage in raids and PvP. Where the simulator found nothing better for your spec, two styles play the same. Also /lazygcore style."] = "输出的激进程度（此角色）。节省：节省法力和生命——做任务时更少停下来吃喝，组队时每波怪后剩下更多法力。均衡：算上休息时间的最快升级，组队时保留法力储备的稳定伤害。最大伤害：立即打出最多伤害——每只怪尽快死亡，最适合团队首领以及有治疗支援时。自动：做任务和地下城时为均衡，团队副本和PvP中为最大伤害。若模拟器未为你的专精找到更好的打法，两种风格的表现相同。也可用 /lazygcore style。"
L["Cheap nuke: more damage per mana here than the DoTs."] = "廉价法术：此处每点法力的伤害高于持续伤害法术。"
