L["Endgame PvE Cat (0/35/16)"] = "满级PvE 猫（0/35/16）"
L["Endgame PvE Bear (0/43/8)"] = "满级PvE 熊（0/43/8）"
L["PvP Cat Shifting Power (0/35/16)"] = "PvP 猫 转换之力（0/35/16）"
L["Leveling 10-60 (6/0/45)"] = "升级 10-60（6/0/45）"
L["Endgame PvE (6/0/45)"] = "满级PvE（6/0/45）"
L["Racial: +50% health and mana regeneration for 15s (+100% while Attuned)."] = "种族技能：15秒内生命值和法力值恢复+50%（同调期间+100%）。"
L["Flame Shock (default) / Earth Shock (shift)"] = "烈焰震击（默认）/ 地震术（Shift）"
L["+33% threat - right-click the buff off (you are not tanking)."] = "威胁值+33% - 右键取消该增益(你不是坦克)。"
L["+33% threat, +90% more Holy threat (and Improved Righteous Fury mitigation)."] = "威胁值+33%，神圣威胁再+90%(以及强化正义之怒的减伤)。"
L["Oath of Light"] = "圣光誓约"
L["Swear it on your tank: your heals on them hit harder (5 min)."] = "对你的坦克立誓：你对其的治疗效果更强(5分钟)。"
