L["Reckless Swings"] = "鲁莽挥击"
L["Next 4 swings give 5 extra Rage (costs health)."] = "接下来4次攻击额外获得5点怒气（消耗生命值）。"
L["Lightning Mastery"] = "闪电掌握"
L["15s: faster Lightning Bolt, Chain Lightning without a cooldown."] = "15秒：闪电箭施法更快，闪电链无冷却。"
L["Totemic Call"] = "图腾召唤"
L["Leveling 10-60, Cruelty first (34/17/0)"] = "升级 10-60，优先残忍（34/17/0）"
L["Endgame PvE Frostfire (0/34/17)"] = "满级PvE 霜火（0/34/17）"
L["Leveling AoE grind 10-60 (0/3/48)"] = "升级 AoE刷怪 10-60（0/3/48）"
L["Build stacks: +12% of your Intellect as spell damage each, for 18s."] = "叠加层数：每层获得智力12%的法术伤害，持续18秒。"
L["Arcane Blast spell damage is up."] = "奥术冲击的法术伤害加成已生效。"
L["R3 with Ice Shards 5: beats Fireball."] = "3级配合寒冰碎片5点：胜过火球术。"
