L["+15% Frost damage for 1 min (+5% while the shield holds)."] = "冰霜伤害提高15%，持续1分钟（护盾存在期间再提高5%）。"
L["Arcane: Arcane Blast stacks to build on elites, bosses, groups and players before Arcane Wrath and Arcane Missiles. Each stack adds 12% of your Intellect as spell damage for 18 seconds from the first Blast, but makes the next Blast cost more (trash always gets one Blast)"] = "奥术：对精英、首领、小队中和玩家时，在奥术之怒和奥术飞弹之前叠加的奥术冲击层数。每层自第一次冲击起18秒内获得智力12%的法术伤害，但下一次冲击消耗更多法力（普通怪始终只打一次冲击）"
