L["LazyGCore's pick for:"] = "LazyGCore推荐用于："
L["Click to follow this build."] = "点击以跟随此天赋方案。"
L["Arms: a two-hander with Sweeping Strikes and Mortal Strike kills fast, and Improved Tactical Mastery keeps your Rage on stance swaps."] = "武器：双手武器配合横扫攻击和致死打击击杀迅速，强化战术掌握让你切换姿态时保留怒气。"
L["Groups need tanks: Protection holds packs with Thunder Clap, Shield Slam and Revenge. Go Fury if you join as damage."] = "队伍需要坦克：防护用雷霆一击、盾牌猛击和复仇拉住整群怪。若以输出身份参加就选狂怒。"
L["Fury: two weapons with Bloodthirst, Flurry and Whirlwind for the most boss damage. Raid tanks stay Protection."] = "狂怒：双持武器配合嗜血、乱舞和旋风斩，对首领伤害最高。团队坦克仍用防护。"
L["Arms: Mortal Strike halves the healing your target takes - the warrior pick for battlegrounds and duels."] = "武器：致死打击使目标受到的治疗减半，是战士打战场和决斗的首选。"
L["Retribution: Seal of Command and Unsealed Wrath hit hard, and you heal yourself instead of resting."] = "惩戒：命令圣印和Unsealed Wrath伤害很高，你可以自我治疗而不用休息。"
L["Protection: Consecration and Holy Shield hold whole packs. Holy if your group needs a healer."] = "防护：奉献和神圣之盾能拉住整群怪。若队伍需要治疗就选神圣。"
L["Holy: big, mana-efficient heals on the tanks with Holy Shock and Light's Vigil."] = "神圣：用神圣震击和Light's Vigil为坦克提供量大且省蓝的治疗。"
L["Retribution: Seal of Command bursts and Repentance controls. Holy if you want to heal in battlegrounds."] = "惩戒：命令圣印打爆发，忏悔控制。想在战场治疗就选神圣。"
L["Beast Mastery: your pet tanks and Bestial Wrath kills fast - the easiest way to level."] = "野兽控制：宠物抗怪，狂野怒火击杀迅速，是最轻松的升级方式。"
L["Marksmanship: steady ranged damage, Trueshot Aura for the group and Barrage on packs."] = "射击：稳定的远程伤害，强击光环增益队伍，弹幕对付成群怪物。"
L["Marksmanship: the strongest sustained ranged damage, and Trueshot Aura helps the raid."] = "射击：最强的持续远程伤害，强击光环增益团队。"
L["Survival: Counterattack, Deterrence and Entrapment keep melee off you."] = "生存：反击、威慑和诱捕让近战远离你。"
L["Combat: Sinister Strike, Shank and Adrenaline Rush with any weapon - fast kills, few deaths."] = "战斗：任何武器都能用邪恶攻击、刺击和冲动，击杀快、死亡少。"
L["Combat: Blade Flurry is the best rogue damage on packs."] = "战斗：剑刃乱舞是盗贼对付成群怪物的最佳伤害。"
L["Assassination: Mutilate and the stronger launch poisons for steady boss damage."] = "刺杀：毁伤和上线时加强的毒药带来稳定的首领伤害。"
L["Subtlety: Premeditation, Preparation and Death Mark for the hardest openers."] = "敏锐：预谋、伺机待发和死亡印记带来最强的开场。"
L["Shadow: Spirit Tap, DoTs and Mind Flay - very little drinking between fights."] = "暗影：精神分流、持续伤害和精神鞭笞，战斗间几乎不用喝水。"
L["Holy: Prayer of Healing and Holy Nova keep a whole group up. Discipline works too."] = "神圣：治疗祷言和神圣新星能保住整个队伍。戒律也可以。"
L["Holy: the strongest group and raid healing."] = "神圣：最强的小队和团队治疗。"
L["Discipline: Penance, strong shields and Power Infusion. Shadow if you want damage."] = "戒律：苦修、强力护盾和能量灌注。想打伤害就选暗影。"
L["Enhancement: Stormstrike every 8 seconds with Flurry and Windfury, and you heal yourself between pulls."] = "增强：每8秒一次风暴打击，配合乱舞和风怒，战斗间还能自我治疗。"
L["Restoration: Chain Heal and totems - groups always look for one."] = "恢复：治疗链和图腾，队伍总在找恢复萨满。"
L["Restoration: Chain Heal and Mana Tide Totem, the shaman role raids want most."] = "恢复：治疗链和法力之潮图腾，是团队最需要的萨满职责。"
L["Elemental: the stronger launch shocks give big burst. Restoration if you heal."] = "元素：上线时加强的震击带来高爆发。治疗就选恢复。"
L["Frost: slows and Frost Nova keep mobs off you; this build pulls whole packs from about 30."] = "冰霜：减速和冰霜新星让怪物近不了身；此方案约30级起就能整群拉怪。"
L["Frost: Blizzard and Cone of Cold on packs, and control when a pull goes wrong."] = "冰霜：用暴风雪和冰锥术对付成群怪物，拉怪失误时还能控场。"
L["Fire: Ignite and Combustion for the most boss damage."] = "火焰：点燃和燃烧带来最高的首领伤害。"
L["Frost: Shatter combos, Ice Block and Ice Barrier."] = "冰霜：碎冰连招、寒冰屏障和寒冰护体。"
L["Affliction: DoTs and drains keep you topped up - almost no downtime."] = "痛苦：持续伤害和吸取让你保持满状态，几乎不用休息。"
L["Destruction: Shadow Bolt and Incinerate damage, Rain of Fire on packs."] = "毁灭：暗影箭和烧尽造成伤害，火焰之雨对付成群怪物。"
L["Destruction: the most single-target damage."] = "毁灭：最高的单体伤害。"
L["Affliction: DoTs, fears and drains wear players down."] = "痛苦：持续伤害、恐惧和吸取拖垮玩家。"
L["Feral: Cat Form kills fast, Bear Form saves bad pulls, Travel Form between quests."] = "野性：猎豹形态击杀快，熊形态挽救失误，任务之间用旅行形态。"
L["Feral Bear: tanks packs with Swipe and Lacerate. Restoration if you heal."] = "野性熊：用横扫和割伤坦住成群怪物。治疗就选恢复。"
L["Restoration: HoTs, Wild Growth and Swiftmend - raids always want druid healers."] = "恢复：持续治疗、野性成长和迅捷治愈，团队总需要德鲁伊治疗。"
L["Feral: shift out of roots and snares. Restoration is a strong battleground healer."] = "野性：变形摆脱定身和减速。恢复是很强的战场治疗。"
-- 1.1.0 (launch changes)
L["following"] = "跟随中"
L["click to follow"] = "点击跟随"
L["Not sure which build to take? Click the one for what you play next."] = "不确定选哪个方案？点击你接下来要玩的内容。"
-- 1.1.0 (launch changes)
L["The Talents page shows the next talent of your build and lets you pick another build. LazyGCore's picks tell you the best build for leveling, dungeons, raids and PvP - one click to follow. While the talent frame is open, your next talent glows."] = "天赋页面显示你方案的下一个天赋，并可选择其他方案。LazyGCore推荐告诉你升级、地下城、团队副本和PvP的最佳方案，一键即可跟随。天赋窗口打开时，你的下一个天赋会发光。"
-- 1.1.0 (launch changes)
L["I use LazyGCore Forever: it shows what to press next, the best talent build for leveling, dungeons, raids and PvP, and ready-made macros. Free on CurseForge: %s"] = "我在用LazyGCore Forever：它会提示下一个该按的技能、升级/地下城/团队副本/PvP的最佳天赋，还有现成的宏。CurseForge免费下载：%s"
L["Know someone who would like LazyGCore? Share it in one click: what to press next, the best talents for leveling, dungeons, raids and PvP, and ready-made macros."] = "认识会喜欢LazyGCore的人吗？一键分享：下一个该按的技能、升级/地下城/团队副本/PvP的最佳天赋，以及现成的宏。"
-- 1.1.0 (launch changes)
L["LazyGCore links open after the boss fight."] = "LazyGCore链接会在首领战结束后打开。"
L["LazyGCore links don't work inside battlegrounds and arenas."] = "LazyGCore链接在战场和竞技场中无法使用。"
L["The game is blocking addon messages right now. Try again in a moment."] = "游戏当前阻止了插件消息。请稍后再试。"
L["That player is offline, so their share can't be fetched."] = "该玩家已离线，无法获取其分享内容。"
L["Too many messages at once. Try again in a few seconds."] = "消息过多。请几秒后再试。"
L["The game didn't send the request. Try again in a moment."] = "游戏未发送该请求。请稍后再试。"
-- 1.1.0 (launch changes)
L["Tip:"] = "提示："
L["Dual Wield Specialization needs a weapon in your off hand."] = "双武器专精需要副手装备武器。"
L["Two-Handed Weapon Specialization only works with a two-handed weapon."] = "双手武器专精只对双手武器生效。"
L["Your Protection talents (Bastion, Shield Slam, Defiance) need a shield."] = "你的防护天赋（堡垒、盾牌猛击、挑衅）需要装备盾牌。"
L["Weaponmaster gives no bonus with daggers or fist weapons."] = "武器大师对匕首和拳套没有加成。"
L["Holy Shield and your Protection talents need a shield."] = "神圣之盾和你的防护天赋需要装备盾牌。"
L["Mutilate needs a dagger in each hand."] = "毁伤需要双手各持一把匕首。"
L["Hemorrhage and Ghostly Strike hit much harder with a dagger in your main hand."] = "主手装备匕首时，出血和鬼魅攻击的伤害会高很多。"
L["Weapon tips"] = "武器提示"
L["Out of combat, a soft tip when your weapons don't suit your talents: a two-hander for Two-Handed Weapon Specialization, a shield for Protection, an off-hand weapon for Dual Wield Specialization, daggers for Mutilate. Also one chat line when you equip them. Never during a fight."] = "脱离战斗时，如果你的武器与天赋不匹配会给出温和提示：双手武器专精需要双手武器，防护需要盾牌，双武器专精需要副手武器，毁伤需要匕首。装备时还会在聊天框提示一行。战斗中从不显示。"
-- 1.1.0 (launch changes)
L["CD"] = "冷却"
L["BUFF"] = "增益"
-- 1.1.0 (launch changes)
L["Damage trinket: use it with your cooldowns."] = "伤害饰品：与你的冷却技能一起使用。"
L["Shows a ready damage trinket in the cooldown slot in fights worth it (elites, dungeons and raids, players, 3+ enemies) - only trinkets whose use effect adds damage for your spec, never defensive or utility ones. Also your PvP trinket when you are stunned or feared (with Suggest defensives on)."] = "在值得的战斗中（精英、地下城和团队副本、玩家、3个以上敌人），在冷却栏显示可用的伤害饰品——只显示使用效果能为你的专精增加伤害的饰品，从不显示防御或功能饰品。被昏迷或恐惧时也会显示你的PvP饰品（需开启建议防御技能）。"
-- 1.1.0 (launch changes)
L["Your swings stored this Seal: swap now, the next hit fires the copies."] = "你的攻击已储存此圣印：现在切换，下一次命中将触发这些副本。"
-- 1.1.0 (launch changes)
L["Fury: two one-handers with Bloodthirst, Whirlwind and Flurry kill fastest while leveling. Arms before you can dual wield (20)."] = "狂怒：双持单手武器配合嗜血、旋风斩和乱舞，升级时击杀最快。能双持之前（20级）用武器。"
-- 1.1.0 (launch changes)
L["Arcane: Arcane Blast stacks with Arcane Power and Presence of Mind - the most boss damage, and mana that lasts the whole fight."] = "奥术：奥术冲击叠层配合奥术强化和气定神闲——首领伤害最高，法力也能撑满整场战斗。"
-- 1.1.0 (launch changes)
L["Auto: each spec's own choice (Subtlety: Rupture on elites, groups and players; Assassination, Combat and leveling: Eviscerate only). Rupture: Rupture first whenever it is missing on a target above 35% health. Eviscerate: never Rupture"] = "“自动”：各专精自行选择（敏锐：对精英、群体和玩家使用割裂；奇袭、战斗和升级：只用刺骨）。“割裂”：目标生命值高于35%且没有割裂时优先割裂。“刺骨”：从不使用割裂"
-- 1.1.0 (launch changes)
L["Show spells on cooldown"] = "显示冷却中的法术"
L["In combat, when nothing is ready, the main icon shows the next spell that comes off cooldown, greyed out with its cooldown. Off: only spells you can press right now are shown."] = "战斗中没有可用技能时，主图标显示下一个冷却结束的法术（灰色并显示冷却）。关闭：只显示现在可以使用的法术。"
L["'Nothing to press' in combat"] = "战斗中的“无需按键”"
L["In combat, when there is nothing to press right now, the main icon shows the LazyGCore logo and 'Nothing to press right now - keep attacking.' Off: the icon and the text stay empty instead."] = "战斗中暂时没有需要按的技能时，主图标显示LazyGCore标志和“现在无需按键——继续攻击。”关闭：图标和文字保持空白。"
-- 1.1.3 (Warlock raid gear option)
L["Raid Gear"] = "团队副本装备"
L["Full raid gear rotation"] = "团队毕业装备循环"
L["Dungeons and raids only. Demonology skips Demonic Brand and the Decimation Soul Fire; Destruction skips Corruption on single targets. In full raid gear this is about 2% more damage on raid bosses, but less in pre-raid gear, so it is off by default"] = "仅限地下城和团队副本。恶魔学识跳过恶魔烙印和屠戮的灵魂之火；毁灭跳过单体目标的腐蚀术。全套团队装备时对团队首领的伤害约提高2%，但在团队前装备下会降低，因此默认关闭"
-- 1.1.3 (welcome tour: your class)
L["LazyGCore for your %s"] = "LazyGCore为你的%s准备的功能"
L["LazyGCore knows every spec of your class: the rotation, your buffs and reminders, and the talents that change what it suggests."] = "LazyGCore了解你职业的每个专精：输出循环、你的增益和提醒，以及会改变建议的天赋。"
L["LazyGCore plays Arms, Fury and Protection with you: Sunder Armor stacks, Heroic Strike when you have rage to spare, threat when you tank, and Battle Shout kept up. It tips you when your weapon does not suit your talents, and LazyGCore's picks show the best build for leveling, dungeons, raids and PvP."] = "LazyGCore支持武器、狂怒和防护：破甲攻击叠层、怒气富余时使用英勇打击、坦克时的仇恨，并保持战斗怒吼。当你的武器不适合你的天赋时会给出提示，LazyGCore推荐会显示升级、地下城、团队副本和PvP的最佳天赋。"
L["LazyGCore plays Retribution, Protection and Holy with you: Seals and Judgements in the right order, Holy Shield and Consecration when you tank, and for Holy a heal target picked from your party or raid, plus Cleanse when someone has a debuff you can remove. It reminds you of your Blessing and tips you when your weapon does not suit your talents."] = "LazyGCore支持惩戒、防护和神圣：按正确顺序使用圣印和审判，坦克时使用神圣之盾和奉献，神圣专精会从小队或团队中选择治疗目标，有人身上有你能驱散的减益时建议清洁术。它会提醒你的祝福，并在武器不适合天赋时给出提示。"
L["LazyGCore plays Beast Mastery, Marksmanship and Survival with you: Hunter's Mark, Serpent Sting, Aimed Shot, Multi-Shot and your Hawks at the right time, and what to do when a mob reaches melee range. It reminds you about your pet and Mend Pet, and keeps the right Aspect up."] = "LazyGCore支持野兽控制、射击和生存：在正确的时机使用猎人印记、毒蛇钉刺、瞄准射击、多重射击和你的雄鹰，并告诉你怪物进入近战范围时该怎么做。它会提醒你的宠物和治疗宠物，并保持正确的守护。"
L["LazyGCore plays Assassination, Combat and Subtlety with you: it builds combo points and picks the finisher - Slice and Dice, Rupture or Eviscerate - at the number of points you choose. It reminds you to apply poisons, can suggest Vanish for damage, and tips you when your weapons do not suit your talents."] = "LazyGCore支持刺杀、战斗和敏锐：积攒连击点，并在你选择的点数时选择终结技（切割、割裂或刺骨）。它会提醒你上毒药，可以建议用消失打出伤害，并在武器不适合天赋时给出提示。"
L["LazyGCore plays Shadow, Holy and Discipline with you. Shadow: Shadow Word: Pain, Mind Blast and Mind Flay in the right order, Shadow Word: Death at the health you choose, and Vampiric Embrace in raids. Holy and Discipline: a heal target picked from your party or raid and the right heal for it. It keeps Inner Fire and your buffs up."] = "LazyGCore支持暗影、神圣和戒律。暗影：按正确顺序使用暗言术：痛、心灵震爆和精神鞭笞，在你选择的生命值使用暗言术：灭，团队中使用吸血鬼的拥抱。神圣和戒律：从小队或团队中选择治疗目标并给出合适的治疗。它会保持心灵之火和你的增益。"
L["LazyGCore plays Elemental, Enhancement and Restoration with you: totems (Call of the Elements before dungeon and raid pulls), your weapon imbue and Water or Lightning Shield kept up, and for Restoration a heal target picked from your party or raid, with Chain Heal when several people are hurt."] = "LazyGCore支持元素、增强和恢复：图腾（在地下城和团队副本开怪前使用元素的召唤），保持武器附魔以及水之护盾或闪电之盾，恢复专精会从小队或团队中选择治疗目标，多人受伤时建议治疗链。"
L["LazyGCore plays Arcane, Fire and Frost with you: Arcane Blast stacks, Scorch stacks for Fire, and your procs. It watches your mana with Mana Gems and Evocation, keeps Arcane Intellect and your armor up, tips you when your weapon does not suit your talents, and the cooldown icon shows when burst cooldowns and damage trinkets are ready."] = "LazyGCore支持奥术、火焰和冰霜：奥术冲击叠层、火焰的灼烧叠层以及你的触发效果。它会用法力宝石和唤醒管理法力，保持奥术智慧和护甲，在武器不适合天赋时给出提示，冷却图标会显示爆发技能和伤害饰品何时就绪。"
L["LazyGCore plays Affliction, Demonology and Destruction with you: your Curse and Bane, Corruption and Immolate refreshed at the right time, and the filler that suits your talents. It suggests Life Tap when you run low on mana, reminds you to summon your demon and keep Demon Armor and your weapon stone up, and suggests Health Funnel when your demon is hurt."] = "LazyGCore支持痛苦、恶魔学识和毁灭：你的诅咒和灾祸，在正确的时机刷新腐蚀术和献祭，并选择适合你天赋的填充技能。法力不足时建议生命分流，提醒你召唤恶魔并保持魔甲术和武器石，恶魔受伤时建议生命通道。"
L["LazyGCore follows your form: Balance with Moonkin Form, Faerie Fire, Moonfire and Insect Swarm; Feral as a cat for damage or a bear for tanking; Restoration with a heal target picked from your party or raid and Rejuvenation kept rolling. It keeps Mark of the Wild and Thorns up."] = "LazyGCore会跟随你的形态：平衡使用枭兽形态、精灵之火、月火术和虫群；野性以猎豹形态输出或熊形态坦克；恢复会从小队或团队中选择治疗目标并保持回春术。它会保持野性印记和荆棘术。"

-- 1.1.4 (keybind size)
L["Custom keybind size"] = "自定义快捷键大小"
L["Lets you change the size of the keybind text on the main icon with Keybind Size. Off: the normal size that follows the icon size. Only applies when Show keybind is on."] = "可通过快捷键大小调整主图标上快捷键文字的大小。关闭：使用随图标大小变化的正常大小。仅在显示快捷键开启时生效。"
L["Keybind Size"] = "快捷键大小"
L["Size of the keybind text compared to normal (1.50 = 50% bigger). Up to 4 fills the whole icon; a big keybind moves to the centre. It never grows past the icon: a long keybind shrinks to fit. Only applies when Custom keybind size is on."] = "快捷键文字相对于正常的大小（1.50 = 大50%）。最高4可填满整个图标；较大的快捷键会移到中央。它永远不会超出图标：较长的快捷键会自动缩小以适应。仅在自定义快捷键大小开启时生效。"

-- 1.1.5 (talent pick order)
L["Show the pick order on the talent frame"] = "在天赋界面显示加点顺序"
L["Puts a number on every talent of your build that still needs points, in the order to take them (1 = next), on all trees, even when you have no point to spend."] = "在你的构筑中每个仍需加点的天赋上标出加点顺序的数字（1 = 下一个），覆盖所有天赋树，即使你没有可用的天赋点也会显示。"
L["Pick numbers"] = "顺序数字"
L["How many upcoming talents get a number: the whole build (default) or only the next 3, 5 or 10. Only applies when Show the pick order on the talent frame is on."] = "显示数字的后续天赋数量：整个构筑（默认），或只显示接下来的3、5或10个。仅在在天赋界面显示加点顺序开启时生效。"
L["Whole build"] = "整个构筑"
L["Next 3"] = "接下来3个"
L["Next 5"] = "接下来5个"
L["Next 10"] = "接下来10个"
